(window.TRENER_PACKS=window.TRENER_PACKS||{})["zadanie-4-svyaz-reshetki"]={"id": "zadanie-4-svyaz-reshetki", "subject": "Химия", "title": "Задание 4 ЕГЭ по химии: химическая связь и кристаллические решётки с нуля до 100 баллов", "version": "26.11.2026", "konspekt": "zadanie-4-svyaz-reshetki", "codes": ["1.4"], "kod": {"p": [{"id": "p1", "t": "Природа химической связи и карта таблицы ФИПИ", "x": "Атомы образуют связи, чтобы получить устойчивую электронную оболочку (октет или дублет) и понизить энергию системы. В чёрно-белой таблице ФИПИ неметаллы лежат в A-группах на диагонали B–Si–As–Te–At и выше/правее неё (плюс водород H), а все побочные подгруппы — металлы; ЭО растёт к фтору F.", "ref": "01.1"}, {"id": "p2", "t": "Ковалентная связь: скрытые неполярные связи и ДАМ", "x": "Ковалентная связь соединяет неметаллы общими парами: между одинаковыми атомами — неполярная (в т.ч. скрытая O–O, S–S, C≡C, C–C внутри сложных веществ!), между разными — полярная. По способу сборки различают обменный и донорно-акцепторный механизмы; после образования донорно-акцепторная связь физически неразличима с обменной.", "ref": "02.1"}, {"id": "p3", "t": "Кратность, σ/π-связи и полярность молекулы", "x": "Одинарная связь состоит из 1 σ, двойная — из 1 σ + 1 π, тройная — из 1 σ + 2 π; чем выше кратность и меньше радиус атомов, тем связь короче и прочнее. Полярность молекулы в целом зависит от её геометрии: в симметричных молекулах (CO2, CH4, CCl4, BF3, SO3) диполи полярных связей взаимно гасятся.", "ref": "03.1"}, {"id": "p4", "t": "Ионная и металлическая связь без ложных переносов", "x": "Ионная связь удерживает катионы и анионы во всех солях (включая соли аммония NH4^{+}, аминов, органические и комплексные соли), щелочах, гидридах, пероксидах и оксидах/гидроксидах металлов (СО +1..+4). Металлическая связь («электронный газ») существует только в простых веществах-металлах (включая жидкую ртуть Hg) и сплавах.", "ref": "04.1"}, {"id": "p5", "t": "Водородная связь: золотое правило H–F, H–O, H–N", "x": "Межмолекулярная водородная связь между одинаковыми молекулами возникает только при наличии прямой ковалентной связи H–F, H–O или H–N. Если водород связан только с углеродом (эфиры, альдегиды, кетоны, третичные амины, CH3F), между собственными молекулами водородной связи нет.", "ref": "05.1"}, {"id": "p6", "t": "Молекулярное vs немолекулярное строение и 4 решётки", "x": "Молекулярное строение имеет только молекулярная решётка (отдельные молекулы); немолекулярное строение объединяет ионную, атомную и металлическую решётки. Тип решётки не совпадает автоматически с типом связи: в SiO2 связь ковалентная полярная, а решётка атомная; в KOH есть ковалентная полярная связь, а решётка ионная.", "ref": "06.1"}, {"id": "p7", "t": "Зависимость физических свойств от типа решётки", "x": "Ионные кристаллы тугоплавки, хрупки и проводят ток только в расплаве/растворе; атомные сверхтвёрды, тугоплавки и нерастворимы; молекулярные легкоплавки, летучи и часто имеют запах; металлические ковки, пластичны и проводят ток в твёрдом состоянии.", "ref": "07.1"}, {"id": "p8", "t": "Алгоритм «Двойной фильтр» для задания № 4 КИМ", "x": "Сначала переведи все 5 названий (особенно тривиальные!) в формулы, затем прогони их через Фильтр 1 (тип решётки или строения), и только оставшихся кандидатов проверь по Фильтру 2 (вид связи или механизм). В ЕГЭ-2027 задание № 4 даёт 1 балл, порядок двух цифр в ответе не важен.", "ref": "08.1"}], "z": [{"id": "z1", "x": "Водород H — неметалл (ЭО ≈ 2,20): он электроотрицательнее Si (1,90) и всех металлов, но слабее C, S, N, Cl, O и F. В HF, несмотря на ΔЭО = 1,78, связь строго ковалентная полярная.", "sk": "eo_bonds", "ref": "01.11"}, {"id": "z2", "x": "Скрытые ковалентные неполярные связи в сложных веществах: пероксиды/надпероксиды (O–O в H2O2, Na2O2, KO2), пирит FeS2 (S–S), карбид кальция CaC2 (C≡C), гидразин N2H4 (N–N), органика с ≥ 2 атомами C (C2H5ONa, CH3COONa).", "sk": "covalent_dam", "ref": "02.7"}, {"id": "z3", "x": "Ловушка «1 углерод vs 2 углерода»: в ацетате CH3COONa и этилате C2H5ONa есть неполярная связь C–C, а в формиате HCOONa и метилате CH3ONa углерод один — неполярной связи нет. В метаниде Al4C3 (Al^{3+} и C^{4−}) связи C–C тоже нет!", "sk": "covalent_dam", "ref": "02.8"}, {"id": "z4", "x": "Главный список ЕГЭ на донорно-акцепторный механизм (ДАМ): соли аммония (NH4^{+}), соли аминов (RNH3^{+}), H3O^{+}, угарный газ CO, комплексы в квадратных скобках [...], HNO3/нитраты/N2O5, O3, BF4^{−}. В NH3 и CO2 ДАМ нет!", "sk": "covalent_dam", "ref": "02.15"}, {"id": "z5", "x": "После образования донорно-акцепторная связь физически неразличима с обменной: в ионе аммония NH4^{+} все 4 связи N–H одинаковы по длине и энергии.", "sk": "covalent_dam", "ref": "02.12"}, {"id": "z6", "x": "Полярные связи в НЕПОЛЯРНОЙ молекуле: CO2, CS2, SO3, BF3, CH4, CCl4, SiH4, C2H2, C6H6. Полярные молекулы: H2O, H2S, SO2, NH3, PH3, HCl, CH3Cl, CHCl3.", "sk": "bond_props", "ref": "03.12"}, {"id": "z7", "x": "В ряду галогеноводородов HF → HCl → HBr → HI радиус галогена растёт → длина связи увеличивается, а энергия (прочность) связи падает.", "sk": "bond_props", "ref": "03.8"}, {"id": "z8", "x": "Соли аммония (NH4Cl, NH4NO3) и соли аминов (CH3NH3Cl) НЕ содержат металлов, но имеют ионную связь, ковалентную полярную связь (в т.ч. ДАМ) и ионную кристаллическую решётку (немолекулярное строение).", "sk": "ionic_metal", "ref": "04.4"}, {"id": "z9", "x": "В бинарных солях и оксидах металлов (NaCl, CaCl2, MgO, NaH, Al4C3) есть ТОЛЬКО ионная связь; в сложных солях и щелочах (KOH, K2SO4, CaCO3, C2H5ONa) обязательно присутствует и ковалентная полярная связь.", "sk": "ionic_metal", "ref": "04.8"}, {"id": "z10", "x": "Высшие кислотные оксиды металлов CrO3 (+6) и Mn2O7 (+7) имеют ковалентную полярную связь и МОЛЕКУЛЯРНУЮ решётку, тогда как оксиды металлов СО +1..+4 (MgO, Fe2O3, Al2O3, ZnO, Cr2O3) в ЕГЭ-4 относятся к ионной решётке.", "sk": "ionic_metal", "ref": "04.9"}, {"id": "z11", "x": "Металлическая связь есть только в простых веществах-металлах (включая жидкую ртуть Hg) и сплавах (бронза, латунь, сталь), но отсутствует в NaCl, Fe2O3, KOH и любых других сложных соединениях металлов.", "sk": "ionic_metal", "ref": "04.13"}, {"id": "z12", "x": "Ловушки на водородную связь: в диметиловом эфире CH3OCH3, этанале CH3CHO, ацетоне CH3COCH3, сложных эфирах, триметиламине (CH3)3N, CH3F, HCl и H2S между одинаковыми молекулами водородных связей НЕТ.", "sk": "h_bonds", "ref": "05.11"}, {"id": "z13", "x": "Канонический список атомной кристаллической решётки в ЕГЭ: алмаз и графит (C), кремний (Si), бор (B), германий (Ge), красный и чёрный фосфор (P), кварц/кремнезём (SiO2), карборунд (SiC), нитрид бора (BN).", "sk": "lattices", "ref": "06.8"}, {"id": "z14", "x": "Аллотропия и решётка: белый фосфор P4 — МОЛЕКУЛЯРНАЯ решётка, а красный/чёрный фосфор — АТОМНАЯ; сухой лёд CO2 — МОЛЕКУЛЯРНАЯ, а кварц SiO2 — АТОМНАЯ; сера S8 и иод I2 — МОЛЕКУЛЯРНАЯ.", "sk": "lattices", "ref": "06.14"}, {"id": "z15", "x": "Твёрдые ионные соли (NaCl) НЕ проводят электрический ток (ионы закреплены в узлах!), но проводят в расплаве и водном растворе. В твёрдом состоянии ток проводят металлы и графит.", "sk": "crystal_props", "ref": "07.8"}, {"id": "z16", "x": "Тривиальные названия ЕГЭ № 4: кремнезём (SiO2, атом.), карборунд (SiC, атом.), сухой лёд (CO2, молек.), пирит (FeS2, ион. + S–S), нашатырь (NH4Cl, ион. + ДАМ), корунд (Al2O3, ион.), негашёная известь (CaO, только ион.).", "sk": "kim4_filter", "ref": "08.6"}]}, "skills": [{"id": "eo_bonds", "name": "Электроотрицательность и природа связей", "ref": "01", "idea": "Определять металлы, неметаллы и направление роста ЭО по чёрно-белой таблице ФИПИ и соотносить природу атомов с видом связи без грубых ошибок на H и HF.", "pre": {"type": "one", "q": "В каком из приведённых веществ химическая связь является ковалентной полярной, несмотря на высокую разницу электроотрицательностей (ΔЭО ≈ 1,78)?", "o": ["Фтороводород HF", "Фторид натрия NaF", "Фтор F2", "Гидрид натрия NaH"], "a": 0, "ex": "Водород H и фтор F — оба неметаллы, у H нет внутренних электронных оболочек, поэтому HF — молекулярное вещество с ковалентной полярной связью (не ионной!).", "d": {"1": "Na — активный металл IA группы, F — неметалл → в NaF ионная связь.", "2": "F2 состоит из двух одинаковых атомов фтора (ΔЭО = 0) → ковалентная неполярная связь.", "3": "NaH — гидрид активного металла (Na^{+}H^{−}) → ионная связь."}}, "pair": {"type": "one", "cases": [["Хлорид хрома(III) CrCl3", "Cr стоит в побочной подгруппе (VIB) — это металл"], ["Хлорид серы(II) SCl2", "S стоит в главной подгруппе (VIA) выше диагонали B–At — это неметалл"]], "q": "В каком веществе электронная плотность химической связи смещена К ВОДОРОДУ (водород более электроотрицателен, чем второй элемент)?", "o": ["Силан SiH4", "Метан CH4", "Аммиак NH3", "Сероводород H2S"], "a": 0, "ex": "Электроотрицательность водорода (2,20) выше, чем у кремния (1,90) и всех металлов, но ниже, чем у C (2,55), S (2,58) и N (3,04). Поэтому в SiH4 пара смещена к H (Si^{+4}H^{−1}4).", "d": {"1": "ЭО(C) = 2,55 > ЭО(H) = 2,20 → электроны смещены к углероду.", "2": "ЭО(N) = 3,04 > ЭО(H) = 2,20 → электроны смещены к азоту.", "3": "ЭО(S) = 2,58 > ЭО(H) = 2,20 → электроны смещены к сере."}}, "fade": {"q": "Восстанови правила работы с чёрно-белой таблицей ФИПИ для определения вида химической связи:", "steps": ["Все элементы побочных подгрупп (B-групп: Cr, Mn, Fe, Cu, Zn) являются {металлами|неметаллами|амфотерными неметаллами}, а водород H относится к {неметаллам|щелочным металлам|благородным газам}.", "В таблице ФИПИ электроотрицательность закономерно растёт {слева направо по периоду и снизу вверх по группе (к фтору F)|сверху вниз по группе и справа налево по периоду|к францию Fr}.", "В ЕГЭ вид связи определяют прежде всего по {природе элементов (Ме/НеМе) и классу вещества|жёсткому вычитанию табличных чисел ΔЭО|агрегатному состоянию при 20 °C}, поэтому HF имеет {ковалентную полярную|ионную|металлическую} связь."]}, "bug": {"q": "Найди ошибочный шаг в определении вида связи по таблице ФИПИ для ряда веществ NaH, H2S, Mn, F2:", "steps": ["NaH: натрий — металл IA группы, водород — неметалл → связь ионная (Na^{+}H^{−}).", "H2S: водород и сера — два разных неметалла → связь ковалентная полярная.", "Mn: марганец стоит в VII группе, как и хлор с фтором, значит это неметалл и связь ковалентная неполярная.", "F2: два одинаковых атома неметалла фтора (ΔЭО = 0) → связь ковалентная неполярная."], "bad": 2, "fix": "Марганец Mn стоит в ПОБОЧНОЙ подгруппе (VIIB), а все элементы побочных подгрупп — исключительно металлы! Значит, в простом веществе Mn связь металлическая.", "why": "Типичная ошибка на чёрно-белой таблице ФИПИ — не проверять подгруппу (главная A или побочная B) и спутать d-металлы VIIB–VIIIB с неметаллами."}, "recall": {"q": "Расскажи по памяти: как по чёрно-белой таблице ФИПИ отделить неметаллы от металлов, куда растёт ЭО и почему в ЕГЭ нельзя слепо полагаться на порог ΔЭО = 1,7.", "points": ["Неметаллы: главные подгруппы (A) на диагонали B–Si–As–Te–At и выше/правее неё, плюс водород H.", "Все побочные подгруппы (B-группы) — строго металлы.", "ЭО растёт вправо по периоду и вверх по группе (к фтору F); благородным газам ЭО в ЕГЭ не приписывают.", "У HF формально ΔЭО ≈ 1,78, но это ковалентная полярная связь (оба элемента — неметаллы)."]}}, {"id": "covalent_dam", "name": "Ковалентная связь: скрытые неполярные и ДАМ", "ref": "02", "idea": "Находить скрытые ковалентные неполярные связи (O–O, S–S, C≡C, N–N, C–C) в сложных веществах и безошибочно выделять вещества с донорно-акцепторным механизмом.", "pre": {"type": "one", "q": "В каком из приведённых сложных веществ ПРИСУТСТВУЕТ ковалентная неполярная связь?", "o": ["Пероксид натрия Na2O2", "Формиат натрия HCOONa", "Карбид алюминия Al4C3", "Сульфид железа(II) FeS"], "a": 0, "ex": "В пероксиде натрия Na2O2 присутствует пероксид-анион [O–O]^{2−}, внутри которого два одинаковых атома кислорода соединены ковалентной неполярной связью O–O.", "d": {"1": "В формиате HCOONa всего один атом углерода — связи C–C нет (только ионная и ковал. полярные C–H, C–O).", "2": "Al4C3 — метанид из отдельных ионов Al^{3+} и C^{4−}, связи C–C в нём нет (в отличие от CaC2!).", "3": "В FeS обычные ионы Fe^{2+} и S^{2−} (только ионная связь); неполярная связь S–S есть в пирите FeS2."}}, "pair": {"type": "one", "cases": [["Аммиак NH3", "Азот образует 3 связи N–H обменным механизмом; остаётся 1 неподелённая пара"], ["Хлорид аммония NH4Cl", "Азот отдаёт свою неподелённую пару катиону H^{+} (пустая 1s) → 4-я связь по ДАМ"]], "q": "В какой паре веществ в ОБОИХ соединениях присутствует связь, образованная по донорно-акцепторному механизму?", "o": ["Угарный газ CO и тетрагидроксоалюминат натрия Na[Al(OH)4]", "Углекислый газ CO2 и аммиак NH3", "Хлорид аммония NH4Cl и метан CH4", "Оксид углерода(IV) CO2 и нитрат натрия NaNO3"], "a": 0, "ex": "В CO третья связь образована по ДАМ (донор O → акцептор C с пустой 2p-орбиталью); в комплексной соли Na[Al(OH)4] лиганды OH^{−} отдают пары на свободные орбитали Al.", "d": {"1": "Ни в CO2 (O=C=O), ни в NH3 донорно-акцепторного механизма нет — там только обменные связи.", "2": "В метане CH4 все 4 связи C–H образованы исключительно по обменному механизму.", "3": "В NaNO3 ДАМ есть (в NO3^{−}), но в CO2 (O=C=O) донорно-акцепторного механизма нет."}}, "fade": {"q": "Закрепи главные ловушки по скрытым неполярным связям и донорно-акцепторному механизму:", "steps": ["В этилате натрия C2H5ONa и ацетате натрия CH3COONa есть ковалентная неполярная связь {C–C|O–O|C–H}, а в формиате HCOONa и метилате CH3ONa её {нет (всего 1 атом углерода)|есть (между O и C)}.", "При донорно-акцепторном механизме один атом (донор) предоставляет {неподелённую электронную пару|один неспаренный электрон}, а другой (акцептор) — {свободную орбиталь|второй неспаренный электрон}.", "После образования в катионе аммония NH4^{+} все четыре связи N–H становятся {полностью равноценными по длине и энергии|разными: три прочные и одна слабая}."]}, "bug": {"q": "Найди ошибочный шаг в разборе списка веществ: 1) NH3  2) CO  3) CaC2  4) NaNO3  5) CH3ONa:", "steps": ["В карбиде кальция CaC2 есть анион [C≡C]^{2−} → присутствует ковалентная неполярная связь C≡C.", "В угарном газе CO третья связь между O и C образована по донорно-акцепторному механизму.", "В аммиаке NH3 у азота есть неподелённая пара, поэтому в молекуле NH3 уже есть связь по донорно-акцепторному механизму.", "В метилате натрия CH3ONa всего один атом углерода, поэтому ковалентной неполярной связи там нет."], "bad": 2, "fix": "Наличие неподелённой пары у азота в NH3 делает аммиак только потенциальным ДОНОРОМ! В самой молекуле NH3 все 3 связи N–H обменные; ДАМ возникает лишь при присоединении H^{+} (в NH4^{+} и солях аммония).", "why": "Самая частая ошибка на ДАМ в задании № 4 — перепутать аммиак NH3 (нет ДАМ) с солями аммония NH4Cl (есть ДАМ)."}, "recall": {"q": "Перечисли по памяти два главных списка ЕГЭ: 1) сложные вещества со скрытой ковалентной неполярной связью; 2) вещества с донорно-акцепторным механизмом.", "points": ["Скрытая неполярная связь: пероксиды/надпероксиды (H2O2, Na2O2, BaO2, KO2 — O–O), пирит FeS2 (S–S), карбид кальция CaC2 (C≡C), гидразин N2H4 (N–N), оксалаты и любая органика с ≥ 2 атомами C (C–C).", "Не путать с ловушками без неполярной связи: HCOONa, CH3ONa, Al4C3, FeS.", "Главный список ДАМ: соли аммония (NH4^{+}), соли аминов (RNH3^{+}), H3O^{+}, CO, комплексные соли [...], HNO3/нитраты/N2O5, O3, BF4^{−}.", "В NH3, CH4 и CO2 донорно-акцепторного механизма нет."]}}, {"id": "bond_props", "name": "Кратность (σ/π), длина, энергия и полярность молекулы", "ref": "03", "idea": "Подсчитывать σ- и π-связи, сравнивать длину и энергию связей по кратности и радиусу атомов, а также строго отличать полярность связи от полярности молекулы.", "pre": {"type": "one", "q": "В какой молекуле связи ковалентные полярные, но САМА МОЛЕКУЛА в целом неполярна (μ = 0)?", "o": ["Углекислый газ CO2", "Сернистый газ SO2", "Аммиак NH3", "Хлороформ CHCl3"], "a": 0, "ex": "В линейной молекуле CO2 (O=C=O, угол 180°) у углерода нет неподелённых пар, поэтому два равных диполя C=O направлены в противоположные стороны и взаимно гасятся.", "d": {"1": "У серы в SO2 есть неподелённая пара → молекула угловая и полярная.", "2": "У азота в NH3 есть неподелённая пара → форма треугольной пирамиды, молекула полярна.", "3": "В CHCl3 вокруг углерода стоят разные атомы (1 H и 3 Cl) → симметрия нарушена, молекула полярна (в отличие от CCl4!)."}}, "pair": {"type": "one", "cases": [["Ацетилен H–C≡C–H", "Две одинарные C–H (2 σ) + одна тройная C≡C (1 σ + 2 π) = 3 σ и 2 π"], ["Углекислый газ O=C=O", "Две двойные связи C=O → каждая даёт 1 σ + 1 π = 2 σ и 2 π"]], "q": "Сколько σ- и π-связей содержится в одной молекуле азота N2 (N≡N)?", "o": ["1 σ-связь и 2 π-связи", "3 σ-связи и 0 π-связей", "2 σ-связи и 1 π-связь", "0 σ-связей и 3 π-связи"], "a": 0, "ex": "Первая связь между любыми двумя атомами — всегда прочная σ-связь (лобовое перекрывание), а вторая и третья — π-связи (боковое перекрывание). В N≡N: 1 σ + 2 π.", "d": {"1": "Две орбитали между одной парой атомов не могут дать больше одной σ-связи вдоль линии ядер.", "2": "В тройной связи всегда ровно 1 σ и 2 π (а не 2 σ и 1 π).", "3": "π-связь не может существовать без σ-связи."}}, "fade": {"q": "Восстанови законы изменения длины, прочности и полярности молекул:", "steps": ["В ряду одинарная → двойная → тройная (C–C → C=C → C≡C) длина связи {уменьшается|увеличивается|не меняется}, а энергия (прочность) связи {растёт|падает}.", "В ряду галогеноводородов HF → HCl → HBr → HI радиус галогена растёт, поэтому связь становится {длиннее и слабее|короче и прочнее}.", "Молекула CCl4 {неполярна (правильный тетраэдр)|полярна}, а молекула CH3Cl {полярна (нарушена симметрия)|неполярна}; молекула CO2 {неполярна (линейная)|полярна}, а SO2 {полярна (угловая из-за неподелённой пары S)|неполярна}."]}, "bug": {"q": "Найди ошибочный шаг в сравнении характеристик связей и молекул CO2, SO2, CH4 и HI:", "steps": ["В молекуле CH4 четыре одинарные полярные связи C–H (4 σ, 0 π), но из-за тетраэдрической симметрии молекула неполярна.", "В молекуле CO2 две двойные связи O=C=O (2 σ и 2 π), геометрия линейная, поэтому молекула неполярна.", "В ряду галогеноводородов самая короткая и самая прочная связь у иодоводорода HI, так как у иода самый большой заряд ядра.", "В молекуле H2O угол связи 104,5° из-за неподелённых пар на кислороде, поэтому молекула воды полярна."], "bad": 2, "fix": "Чем больше радиус атома (у I он максимален среди галогенов), тем больше расстояние между ядрами — значит, связь в HI самая ДЛИННАЯ и самая СЛАБАЯ, а самая короткая и прочная — в HF!", "why": "Рост заряда ядра вниз по группе сопровождается появлением новых электронных слоёв, поэтому радиус атома растёт, а связь H–Гал удлиняется и ослабевает."}, "recall": {"q": "Назови по памяти состав одинарной/двойной/тройной связи по σ и π, два закона длины/энергии и списки неполярных и полярных молекул с полярными связями.", "points": ["Одинарная = 1 σ; двойная = 1 σ + 1 π; тройная = 1 σ + 2 π; σ прочнее π.", "Чем выше кратность (C≡C > C=C > C–C) и меньше радиусы атомов (HF > HCl > HBr > HI), тем короче и прочнее связь.", "Неполярные молекулы с полярными связями: CO2, CS2, SO3, BF3, CH4, CCl4, SiH4, C2H2, C6H6.", "Полярные молекулы: H2O, H2S, SO2, NH3, PH3, HCl, HF, CH3Cl, CHCl3, CO."]}}, {"id": "ionic_metal", "name": "Ионная и металлическая связь: сложные соли и сплавы", "ref": "04", "idea": "Раскладывать все виды химической связи в бинарных, сложных, аммонийных, органических и комплексных солях, а также безошибочно выделять металлическую связь.", "pre": {"type": "one", "q": "Какие виды химической связи одновременно присутствуют в этилате натрия C2H5ONa (веществе из Демоверсии ЕГЭ-2027)?", "o": ["Ионная, ковалентная полярная и ковалентная неполярная", "Только ионная и ковалентная полярная", "Только ковалентная полярная и ковалентная неполярная", "Ионная и металлическая"], "a": 0, "ex": "В C2H5ONa (CH3–CH2–O^{−} Na^{+}): между O^{−} и Na^{+} — ионная; между C–H и C–O — ковалентная полярная; между двумя углеродами C–C — ковалентная неполярная!", "d": {"1": "Забыта связь C–C внутри этильного радикала CH3–CH2– (она ковалентная неполярная).", "2": "Этилат натрия — солеподобное ионное соединение (алкоголят), между O^{−} и Na^{+} связь ионная.", "3": "Металлической связи в солях и алкоголятах металлов никогда не бывает."}}, "pair": {"type": "one", "cases": [["Хлорид кальция CaCl2", "Бинарная соль из одноатомных ионов Ca^{2+} и Cl^{−} → ТОЛЬКО ионная связь"], ["Гидроксид калия KOH", "Сложный анион OH^{−} → ионная связь (K^{+}···OH^{−}) + ковалентная полярная (O–H)"]], "q": "В каком из перечисленных веществ НЕТ металлической связи?", "o": ["Оксид железа(III) Fe2O3", "Жидкая ртуть Hg", "Бронза (сплав меди и олова)", "Натрий Na"], "a": 0, "ex": "Металлическая связь существует только в простых веществах-металлах (включая жидкую ртуть Hg!) и их сплавах. В оксиде железа Fe2O3 — ионная связь.", "d": {"1": "Ртуть Hg — простое вещество-металл; даже в жидком виде между атомами/катионами сохраняется металлическая связь.", "2": "Бронза — металлический сплав, в нём действует металлическая связь.", "3": "Натрий Na — простое вещество-металл с металлической связью."}}, "fade": {"q": "Разбери по полочкам сложные случаи ионной и металлической связи на 100 баллов:", "steps": ["В хлориде аммония NH4Cl и хлориде метиламмония CH3NH3Cl нет атомов металла, но между катионом и Cl^{−} связь {ионная|только ковалентная полярная|металлическая}, а внутри катиона — ковалентная полярная с {донорно-акцепторным механизмом|только обменным механизмом}.", "В оксиде хрома(III) Cr2O3 связь в модели ЕГЭ-4 {ионная|ковалентная неполярная}, а в высшем кислотном оксиде хрома(VI) CrO3 — {ковалентная полярная (молекулярное строение)|ионная (атомная решётка)}.", "Металлическая связь в ЕГЭ-4 встречается исключительно в {простых веществах-металлах (включая жидкую Hg) и сплавах|любых веществах, содержащих атом металла в формуле}."]}, "bug": {"q": "Найди ошибочный шаг при раскладке всех видов связи в списке: NH4NO3, K2[Zn(OH)4], CuSO4, Mn2O7:", "steps": ["В нитрате аммония NH4NO3 есть ионная связь (NH4^{+} и NO3^{−}) и ковалентная полярная связь с ДАМ.", "В тетрагидроксоцинкате калия K2[Zn(OH)4] есть ионная связь, ковалентная полярная (O–H) и ДАМ внутри комплексного аниона.", "В сульфате меди(II) CuSO4 содержится металл медь, значит в кристалле присутствуют металлическая, ионная и ковалентная полярная связи.", "В оксиде марганца(VII) Mn2O7 марганец имеет высшую с.о. +7, поэтому связь ковалентная полярная и строение молекулярное."], "bad": 2, "fix": "В CuSO4 есть только ИОННАЯ (между Cu^{2+} и SO4^{2−}) и КОВАЛЕНТНАЯ ПОЛЯРНАЯ (внутри SO4^{2−}) связи. Металлической связи в солях не существует!", "why": "Антипаттерн «металл в формуле = металлическая связь» мгновенно обнуляет балл в задании № 4."}, "recall": {"q": "Объясни по памяти: 1) какие вещества имеют ионную связь без металла; 2) в каких солях есть сразу 3 вида связи; 3) границу модели для CrO3 и Mn2O7.", "points": ["Ионная связь без металла: все соли аммония (NH4Cl, NH4NO3, (NH4)2SO4) и соли аминов (CH3NH3Cl, C6H5NH3Cl).", "Сразу 3 вида связи (ионная + КПС + КНС): органические соли/алкоголяты с ≥ 2 C (C2H5ONa, CH3COONa, C6H5ONa), оксалаты (Na2C2O4).", "Высшие кислотные оксиды CrO3 (+6) и Mn2O7 (+7) имеют ковалентную полярную связь и молекулярную решётку (в отличие от MgO, Al2O3, ZnO, Fe2O3, Cr2O3).", "Металлическая связь — только в металлах (в т.ч. жидкая Hg) и сплавах."]}}, {"id": "h_bonds", "name": "Водородная связь (правило F, O, N) и силы Ван-дер-Ваальса", "ref": "05", "idea": "Применять правило прямой связи H–F, H–O, H–N по структурной формуле, отсекать ловушки (эфиры, альдегиды, кетоны, третичные амины, HCl, H2S) и понимать аномалию температур кипения.", "pre": {"type": "one", "q": "Между молекулами какого органического вещества ОБРАЗУЮТСЯ межмолекулярные водородные связи?", "o": ["Этанол CH3–CH2–OH", "Диметиловый эфир CH3–O–CH3", "Этаналь CH3–CHO", "Триметиламин (CH3)3N"], "a": 0, "ex": "В этаноле есть прямая ковалентная связь –O–H, поэтому между его молекулами возникают прочные водородные связи (t_кип = +78 °C).", "d": {"1": "Диметиловый эфир — изомер этанола, но O связан только с двумя атомами C; связи O–H нет (газ, −24 °C).", "2": "В альдегидах (–CH=O) водород связан с углеродом, а не с кислородом — между молекулами чистого этаналя Н-связей нет.", "3": "В третичном амине (CH3)3N у азота нет ни одного атома H — связи N–H отсутствуют."}}, "pair": {"type": "one", "cases": [["Вода H2O (M = 18)", "Есть прямая связь H–O → водородные связи поднимают t_кип до +100 °C"], ["Сероводород H2S (M = 34)", "Сера крупнее и слабее O → водородных связей нет, t_кип = −60 °C"]], "q": "В какой паре НЕОРГАНИЧЕСКИХ веществ водородные связи образуются в ОБОИХ веществах?", "o": ["Фтороводород HF и аммиак NH3", "Хлороводород HCl и вода H2O", "Фосфин PH3 и сероводород H2S", "Фтороводород HF и силан SiH4"], "a": 0, "ex": "Только три элемента (F, O, N) при прямой связи с H дают межмолекулярную водородную связь в курсе ЕГЭ: в HF (H–F) и NH3 (N–H) она есть.", "d": {"1": "У хлора в HCl слишком большой радиус и ниже ЭО — в школьном курсе ЕГЭ-4 у HCl водородных связей нет.", "2": "Ни фосфор в PH3, ни сера в H2S не входят в тройку F, O, N.", "3": "В силане SiH4 водород связан с кремнием — водородных связей нет."}}, "fade": {"q": "Проверь золотое правило водородной связи и разграничение «чистое вещество vs водный раствор»:", "steps": ["Межмолекулярная водородная связь между одинаковыми молекулами возникает только при наличии прямой ковалентной связи {H–F, H–O или H–N|H–Cl, H–S или H–C|любой связи с участием H}.", "Среди аминов водородные связи между собственными молекулами образуют {первичные и вторичные амины (есть N–H)|только третичные амины|все амины без исключения}; среди эфиров (простых и сложных) водородных связей между собственными молекулами {нет|есть}.", "Силы Ван-дер-Ваальса действуют между {любыми молекулами и растут с ростом молярной массы (F2 < Cl2 < Br2 < I2)|только полярными молекулами}, а внутримолекулярные водородные связи удерживают {вторичную структуру белков и две цепи ДНК|первичную структуру белка}."]}, "bug": {"q": "Найди ошибочный шаг в отборе веществ с межмолекулярной водородной связью из списка: 1) CH3COOH  2) CH3COOCH3  3) C6H5OH  4) CH3F  5) NH3:", "steps": ["В уксусной кислоте CH3COOH есть группа –O–H → образует прочные димеры с водородными связями.", "В метилацетате CH3COOCH3 нет связи O–H (оба кислорода связаны с углеродом) → водородных связей нет.", "В фторметане CH3F присутствуют и водород H, и самый электроотрицательный элемент фтор F → значит, образуются водородные связи.", "В феноле C6H5OH (группа –OH) и аммиаке NH3 (связи N–H) водородные связи есть."], "bad": 2, "fix": "В фторметане CH3–F все три атома водорода связаны с УГЛЕРОДОМ, а не с фтором! Прямой связи H–F нет, поэтому между молекулами CH3F водородные связи не образуются.", "why": "Антипаттерн «смотреть на буквы в брутто-формуле» ломается на CH3F, CH3OCH3, CH3CHO и CH3COOCH3."}, "recall": {"q": "Назови по памяти классы с водородной связью и 7 главных классов-ловушек ЕГЭ, где водородной связи между собственными молекулами нет.", "points": ["Есть Н-связи: HF, H2O, H2O2, NH3, N2H4, оксокислоты (HNO3, H2SO4, H3PO4), спирты, фенолы, карбоновые кислоты, первичные и вторичные амины, углеводы, аминокислоты, белки, ДНК.", "7 главных ловушек (НЕТ между своими молекулами): простые эфиры, сложные эфиры, альдегиды, кетоны, третичные амины, галогеналканы (включая CH3F), а также HCl/HBr/HI/H2S/PH3.", "Важно: в водном растворе ацетон и альдегиды образуют Н-связи с водой, но в № 4 всегда спрашивают про связи между молекулами самого вещества."]}}, {"id": "lattices", "name": "Молекулярное vs немолекулярное строение и 4 решётки", "ref": "06", "idea": "Мгновенно делить вещества на молекулярные и немолекулярные, помнить канонический список атомных решёток и не попадаться на ловушки аллотропии и высших оксидов.", "pre": {"type": "one", "q": "В какой паре ОБА вещества имеют АТОМНУЮ кристаллическую решётку?", "o": ["Оксид кремния(IV) SiO2 и карбид кремния SiC", "Углекислый газ CO2 и оксид кремния(IV) SiO2", "Белый фосфор P4 и графит C", "Иод I2 и кремний Si"], "a": 0, "ex": "SiO2 (кварц, кремнезём) и SiC (карборунд) входят в короткий канонический список атомных решёток ЕГЭ (C алмаз/графит, Si, B, Ge, красный/чёрный P, SiO2, SiC, BN).", "d": {"1": "CO2 (сухой лёд) состоит из отдельных линейных молекул O=C=O → молекулярная решётка!", "2": "Белый фосфор P4 состоит из молекул P4 → молекулярная решётка (атомная у красного и чёрного P).", "3": "Иод I2 легко возгоняется и имеет молекулярную решётку."}}, "pair": {"type": "one", "cases": [["Серная кислота H2SO4", "Жидкость при н.у., в твёрдом виде состоит из отдельных молекул → МОЛЕКУЛЯРНАЯ решётка"], ["Хлорид аммония NH4Cl", "Соль из ионов NH4^{+} и Cl^{−} → ИОННАЯ решётка (НЕМОЛЕКУЛЯРНОЕ строение!)"]], "q": "Какая пара веществ имеет НЕМОЛЕКУЛЯРНОЕ строение?", "o": ["Нитрид бора BN и нитрат аммония NH4NO3", "Фосфорная кислота H3PO4 и глюкоза C6H12O6", "Белый фосфор P4 и оксид хрома(VI) CrO3", "Сухой лёд CO2 и кристаллическая сера S8"], "a": 0, "ex": "Немолекулярное строение — это ионная, атомная или металлическая решётка. BN имеет атомную решётку, а NH4NO3 — ионную; оба немолекулярного строения!", "d": {"1": "Кислоты (H3PO4, H2SO4, HNO3) и несолевая органика (глюкоза) имеют молекулярное строение.", "2": "Белый фосфор P4 и высший кислотный оксид CrO3 имеют молекулярную решётку.", "3": "CO2 и S8 — классические вещества молекулярного строения."}}, "fade": {"q": "Заполни каноническую классификацию решёток и аллотропных модификаций ЕГЭ:", "steps": ["К НЕМОЛЕКУЛЯРНОМУ строению относятся ровно три типа решёток: {ионная, атомная и металлическая|молекулярная, ионная и атомная|только ионная и металлическая}.", "Белый фосфор P4 имеет {молекулярную|атомную} решётку, а красный и чёрный фосфор — {атомную|молекулярную}; графит в ЕГЭ-4 относят к {атомной решётке (немолекулярное строение)|молекулярной решётке}.", "Оксид хрома(III) Cr2O3 и оксид алюминия Al2O3 в модели ЕГЭ-4 имеют {ионную|молекулярную} решётку, а высшие кислотные оксиды CrO3 и Mn2O7 — {молекулярную|ионную}."]}, "bug": {"q": "Найди ошибочный шаг в определении строения веществ: 1) NH4Cl  2) H2SO4  3) SiO2  4) S8:", "steps": ["SiO2 (кварц) — атомная кристаллическая решётка → немолекулярное строение.", "S8 (кристаллическая сера) — молекулярная решётка → молекулярное строение.", "NH4Cl состоит только из неметаллов (N, H, Cl), поэтому оно имеет молекулярное строение.", "H2SO4 (серная кислота) — молекулярная решётка → молекулярное строение."], "bad": 2, "fix": "Правило «только неметаллы = молекулярное строение» не работает! NH4Cl — это соль аммония с ионной решёткой (немолекулярное строение), как и атомные кристаллы C, Si, SiO2, SiC, BN.", "why": "Опора на ложное правило «нет металла → молекулярное строение» приводит к ошибкам и на солях аммония, и на атомных решётках."}, "recall": {"q": "Воспроизведи по памяти полный список атомных решёток ЕГЭ и объясни, почему CO2 — газ, а SiO2 — тугоплавкий кварц.", "points": ["Простые вещества с атомной решёткой: алмаз и графит (C), Si, B, Ge, красный и чёрный P.", "Сложные вещества с атомной решёткой: SiO2 (кварц/кремнезём), SiC (карборунд), BN (нитрид бора).", "В CO2 маленький углерод (2-й период) образует двойные π-связи O=C=O → отдельные молекулы; крупный кремний Si (3-й период) не образует прочных π-связей с O, а сшивается 4 одинарными связями Si–O в 3D-каркас.", "Молекулярная решётка: газы, жидкости (кроме Hg), кислоты (H2SO4, HNO3, H3PO4), P4, S8, I2, CrO3, Mn2O7, глюкоза."]}}, {"id": "crystal_props", "name": "Физические свойства кристаллов по типу решётки", "ref": "07", "idea": "Узнавать тип кристаллической решётки по физическому паспорту (t_пл, хрупкость vs ковкость, электропроводность в твёрдом виде и расплаве, запах и растворимость).", "pre": {"type": "one", "q": "Безымянное твёрдое вещество X имеет высокую температуру плавления (~800 °C), хрупкое, НЕ проводит электрический ток в твёрдом состоянии, но хорошо проводит в расплаве и водном растворе. Какая у него кристаллическая решётка?", "o": ["Ионная", "Металлическая", "Атомная", "Молекулярная"], "a": 0, "ex": "Высокая t_пл + хрупкость (сдвиг слоёв сталкивает одноимённые заряды!) + электропроводность только в расплаве/растворе — точный паспорт ионной решётки (например, NaCl).", "d": {"1": "Металлы ковки/пластичны и отлично проводят ток уже в твёрдом состоянии.", "2": "Атомные кристаллы практически нерастворимы и не проводят ток в расплаве.", "3": "Молекулярные кристаллы имеют низкую t_пл и не проводят ток в расплаве."}}, "pair": {"type": "one", "cases": [["Ионный кристалл (NaCl)", "При ударе слои сдвигаются → «+» напротив «+» → отталкивание → ХРУПКИЙ"], ["Металл (Cu, Fe)", "При ударе свободный «электронный газ» сохраняет связь между слоями → КОВКИЙ и ПЛАСТИЧНЫЙ"]], "q": "Какое свойство служит самым надёжным признаком МОЛЕКУЛЯРНОЙ кристаллической решётки у твёрдого вещества (например, иода, камфоры, фенола)?", "o": ["Низкая температура плавления, летучесть (возгонка) и наличие запаха", "Высокая твёрдость и нерастворимость в воде", "Электропроводность в твёрдом состоянии и металлический блеск", "Электропроводность расплава при высокой температуре плавления"], "a": 0, "ex": "Чтобы твёрдое вещество пахло и легко возгонялось, его частицы должны легко отрываться с поверхности — это возможно только при слабых межмолекулярных силах в молекулярной решётке.", "d": {"1": "Высокая твёрдость и нерастворимость — признаки атомной решётки (кварц, алмаз).", "2": "Электропроводность в твёрдом виде и блеск — признаки металлической решётки.", "3": "Электропроводность расплава при высокой t_пл — признак ионной (или металлической) решётки."}}, "fade": {"q": "Сопоставь физические свойства с типом кристаллической решётки:", "steps": ["Твёрдый хлорид натрия NaCl {не проводит электрический ток (ионы закреплены в узлах)|проводит ток за счёт свободных электронов}, но его расплав и водный раствор ток {проводят|не проводят}.", "Сверхвысокая температура плавления (> 1500 °C), максимальная твёрдость и практическая нерастворимость в воде характерны для {атомной решётки (алмаз, SiO2, SiC)|молекулярной решётки|ионной решётки}.", "Среди веществ с атомной решёткой уникальным исключением, которое мягко и проводит электрический ток в твёрдом состоянии, является {графит|алмаз|кварц SiO2}."]}, "bug": {"q": "Найди ошибочный шаг в рассуждении о свойствах веществ NaCl, Cu, SiO2 и I2:", "steps": ["Медь Cu обладает металлической решёткой, поэтому она пластична и проводит ток в твёрдом состоянии.", "Поваренная соль NaCl состоит из заряженных ионов Na^{+} и Cl^{−}, поэтому её сухие кристаллы хорошо проводят электрический ток.", "Кварц SiO2 имеет атомную решётку, поэтому он тугоплавок, очень твёрд и нерастворим в воде.", "Иод I2 имеет молекулярную решётку, поэтому он легко возгоняется и обладает резким запахом."], "bad": 1, "fix": "В твёрдом кристалле NaCl ионы жёстко зафиксированы в узлах и не могут свободно перемещаться — поэтому сухая соль ток НЕ проводит! Проводимость появляется только в расплаве или водном растворе.", "why": "Электропроводность требует не просто наличия зарядов, а СВОБОДНЫХ подвижных носителей заряда."}, "recall": {"q": "Сравни по памяти физические паспорта всех 4 решёток по признакам: t_пл, механика (хрупкость/ковкость), электропроводность (тв./распл.) и запах.", "points": ["Ионная: высокая t_пл, твёрдые и хрупкие, не пахнут, не проводят ток твёрдыми, но проводят в расплаве и водном растворе.", "Атомная: очень высокая t_пл, сверхтвёрдые, не пахнут, нерастворимы, изоляторы (кроме графита и полупроводников Si, Ge).", "Молекулярная: низкие t_пл/t_кип, мягкие, летучие, часто пахнут, расплавы не проводят ток.", "Металлическая: ковкие и пластичные, блеск, отлично проводят ток в твёрдом и жидком состоянии."]}}, {"id": "kim4_filter", "name": "Алгоритм «Двойной фильтр» и тривиальные названия (КИМ № 4)", "ref": "08", "idea": "Переводить тривиальные названия КИМ № 4 в формулы и безошибочно решать любые двухкритериальные задания ЕГЭ-2027 за 40 секунд методом двойного фильтра.", "pre": {"type": "one", "q": "В чём заключается главное правило метода «Двойной фильтр» при решении задания № 4 ЕГЭ-2027?", "o": ["Сначала перевести все 5 названий в формулы, затем отдельно применить Фильтр 1 (решётка/строение) и только к оставшимся — Фильтр 2 (тип связи/механизм)", "Сразу выбирать первые два вещества, в которых нашлась нужная химическая связь", "Всегда искать вещества с металлом в составе", "Записывать две цифры строго в порядке убывания, иначе ответ не засчитают"], "a": 0, "ex": "По статистике ФИПИ 40,5% выпускников теряют балл в № 4, проверяя лишь один критерий или ошибаясь в тривиальном названии. Двойной фильтр полностью исключает эту ошибку.", "d": {"1": "Проверка только одного критерия — главная причина потери балла (например, выбрать CO вместо NH4Cl, забыв фильтр «немолекулярное строение»).", "2": "В заданиях на атомную/молекулярную решётку или соли аммония металлов вообще нет.", "3": "В задании № 4 ЕГЭ-2027 порядок двух цифр значения не имеет (35 и 53 равноценны), но обе цифры должны быть верны."}}, "pair": {"type": "one", "cases": [["Нашатырь (NH4Cl)", "Соль аммония → ионная решётка, ионная + КПС + ДАМ"], ["Нашатырный спирт (NH3·H2O)", "Водный раствор аммиака, не соль! Не путать с нашатырём!"]], "q": "В какой паре ОБА тривиальных названия соответствуют веществам с АТОМНОЙ кристаллической решёткой?", "o": ["Кремнезём (SiO2) и карборунд (SiC)", "Сухой лёд (CO2) и кремнезём (SiO2)", "Пирит (FeS2) и корунд (Al2O3)", "Негашёная известь (CaO) и известняк (CaCO3)"], "a": 0, "ex": "Кремнезём (SiO2) и карборунд (SiC) — оба имеют атомную кристаллическую решётку и ковалентную полярную связь.", "d": {"1": "Сухой лёд — это твёрдый CO2 с молекулярной решёткой!", "2": "Пирит FeS2 и корунд Al2O3 в ЕГЭ-4 имеют ионную решётку.", "3": "CaO и CaCO3 имеют ионную решётку."}}, "fade": {"q": "Прогони кейс Демоверсии ФИПИ ЕГЭ-2027 через «Двойной фильтр» (условие: ковалентная полярная связь + ионная решётка; ряд: 1) CaCl2, 2) P2O5, 3) этилат натрия, 4) NH3, 5) KOH):", "steps": ["Шаг 1 — переводим названия в формулы: этилат натрия — это {C2H5ONa|CH3COONa|C2H5OH}, а гидроксид калия — KOH.", "Шаг 2 — Фильтр 1 (ионная кристаллическая решётка): сразу отбрасываем молекулярные вещества {P2O5 и NH3|CaCl2 и KOH|этилат натрия и NH3}. Остаются CaCl2, C2H5ONa, KOH.", "Шаг 3 — Фильтр 2 (есть ковалентная полярная связь): отбрасываем бинарный {CaCl2 (в нём только ионная связь)|KOH (в нём нет ковалентной связи)} → верный ответ {35 (или 53)|15|24}."]}, "bug": {"q": "Найди ошибочный шаг в решении задания № 4: «Выберите два вещества немолекулярного строения, в которых есть ковалентная неполярная связь»: 1) пероксид водорода  2) пирит  3) формиат натрия  4) карбид кальция  5) хлорид натрия:", "steps": ["Переводим названия в формулы: 1) H2O2, 2) FeS2, 3) HCOONa, 4) CaC2, 5) NaCl.", "В пирите FeS2 есть дисульфидный мостик S–S, а в карбиде кальция CaC2 — тройная связь C≡C (обе неполярные, и оба вещества имеют ионную решётку).", "В пероксиде водорода H2O2 есть ковалентная неполярная связь O–O, значит это вещество немолекулярного строения и оно тоже подходит под условие.", "В формиате натрия HCOONa всего один атом углерода (связи C–C нет), а в NaCl только ионная связь — они не подходят."], "bad": 2, "fix": "Пероксид водорода H2O2 — жидкость при н.у. с МОЛЕКУЛЯРНЫМ строением (хотя в нём есть неполярная связь O–O). Поэтому Фильтр 1 (немолекулярное строение) сразу отсекает H2O2! Верный ответ: 24.", "why": "Наличие ковалентной неполярной связи ничего не говорит о немолекулярности: в H2O2, O2, N2, Cl2, S8, I2, P4 она есть, но все они молекулярного строения."}, "recall": {"q": "Перечисли 4 шага алгоритма «Двойной фильтр» и 6 самых коварных тривиальных названий для задания № 4.", "points": ["1) Перевести все 5 названий в формулы; 2) Фильтр 1 (решётка/строение); 3) Фильтр 2 (вид связи/механизм); 4) Обратная 5-секундная проверка обеих цифр.", "Кремнезём = SiO2 (атомная); карборунд = SiC (атомная); сухой лёд = CO2 (молекулярная).", "Пирит = FeS2 (ионная + S–S); нашатырь = NH4Cl (ионная + КПС + ДАМ); корунд = Al2O3 (ионная).", "Негашёная известь = CaO (только ионная); гашёная известь = Ca(OH)2 (ионная + КПС); этилат натрия = C2H5ONa (ионная + КПС + C–C)."]}}], "figs": {}, "tab": [{"id": "t_bond_types", "t": "Комбинированные связи в сложных веществах и ловушки № 4", "k": "Вещество", "km": "веществом", "ref": "04.8", "n": 4, "lv3": ["C2H5ONa (этилат натрия)", "HCOONa (формиат натрия)", "FeS2 (пирит)", "Al4C3 (карбид алюминия)", "NH4Cl (хлорид аммония)", "Na2O2 (пероксид натрия)", "CaC2 (карбид кальция)"], "cols": [{"t": "Набор видов связи", "sk": "ionic_metal", "n": 4, "q": "Какой полный набор видов химической связи присутствует в веществе {x}?", "m": "набором видов связи", "mq": "Выберите {k} вещества, для которых характерен набор связей «{v}»:"}, {"t": "Скрытая ковал. неполярная связь?", "sk": "covalent_dam", "n": 4, "q": "Присутствует ли ковалентная неполярная связь в веществе {x}?", "m": "наличием ковалентной неполярной связи", "mq": "Выберите {k} вещества, для которых ответ на вопрос о ковалентной неполярной связи: «{v}»:"}], "rows": [["CaCl2 (хлорид кальция)", "Только ионная", "Нет"], ["Al4C3 (карбид алюминия)", "Только ионная", "Нет"], ["KOH (гидроксид калия)", "Ионная + ковал. полярная", "Нет"], ["HCOONa (формиат натрия)", "Ионная + ковал. полярная", "Нет"], ["NH4Cl (хлорид аммония)", "Ионная + ковал. полярная (+ ДАМ)", "Нет"], ["Na2O2 (пероксид натрия)", "Ионная + ковал. неполярная", "Да (O–O)"], ["FeS2 (пирит)", "Ионная + ковал. неполярная", "Да (S–S)"], ["CaC2 (карбид кальция)", "Ионная + ковал. неполярная", "Да (C≡C)"], ["C2H5ONa (этилат натрия)", "Ионная + ковал. полярная + ковал. неполярная", "Да (C–C)"], ["CH3COONa (ацетат натрия)", "Ионная + ковал. полярная + ковал. неполярная", "Да (C–C)"], ["H2O2 (пероксид водорода)", "Ковал. полярная + ковал. неполярная", "Да (O–O)"], ["Cu (медь) / бронза", "Только металлическая", "Нет"]], "rw": {"C2H5ONa (этилат натрия)": "Сразу 3 вида связи: O^{−}···Na^{+} (ионная), C–H/C–O (полярная), C–C (неполярная).", "HCOONa (формиат натрия)": "Всего один атом углерода → связи C–C нет (в отличие от ацетата CH3COONa!).", "Al4C3 (карбид алюминия)": "Метанид из отдельных ионов Al^{3+} и C^{4−}: только ионная связь, связи C–C нет.", "NH4Cl (хлорид аммония)": "Металлов нет, но между NH4^{+} и Cl^{−} — ионная связь, внутри NH4^{+} — КПС (+ ДАМ)."}}, {"id": "t_dam_map", "t": "Карта донорно-акцепторного механизма (ДАМ) в ЕГЭ-2027", "k": "Вещество / ион", "km": "веществом", "ref": "02.15", "n": 4, "lv3": ["CO (угарный газ)", "CO2 (углекислый газ)", "NH3 (аммиак)", "Na[Al(OH)4]", "HNO3 / NaNO3", "O3 (озон)", "[CH3NH3]Cl"], "cols": [{"t": "Есть ли ДАМ в модели ЕГЭ-4?", "sk": "covalent_dam", "n": 4, "q": "Есть ли в веществе {x} связь, образованная по донорно-акцепторному механизму (в модели ЕГЭ-4)?", "m": "наличием ДАМ", "mq": "Выберите {k} вещества, для которых ответ о наличии ДАМ: «{v}»:"}, {"t": "Строение вещества", "sk": "lattices", "n": 4, "q": "Какое строение (молекулярное или немолекулярное) имеет вещество {x}?", "m": "типом строения", "mq": "Выберите {k} вещества со строением «{v}»:"}], "rows": [["NH4Cl (хлорид аммония)", "Да", "Немолекулярное (ионная)"], ["[CH3NH3]Cl (хлорид метиламмония)", "Да", "Немолекулярное (ионная)"], ["Na[Al(OH)4]", "Да", "Немолекулярное (ионная)"], ["K2[Zn(OH)4]", "Да", "Немолекулярное (ионная)"], ["NaNO3 (нитрат натрия)", "Да", "Немолекулярное (ионная)"], ["CO (угарный газ)", "Да", "Молекулярное"], ["HNO3 (азотная кислота)", "Да", "Молекулярное"], ["O3 (озон)", "Да", "Молекулярное"], ["NH3 (аммиак)", "Нет", "Молекулярное"], ["CO2 (углекислый газ)", "Нет", "Молекулярное"], ["CH4 (метан)", "Нет", "Молекулярное"]], "rw": {"CO (угарный газ)": "Донор — кислород O, акцептор — углерод C (пустая 2p-орбиталь), тройная связь C≡O.", "NH3 (аммиак)": "В самом NH3 все 3 связи обменные; ДАМ появляется только при переходе в NH4^{+}.", "CO2 (углекислый газ)": "Все 4 связи (O=C=O) образованы по обменному механизму, ДАМ нет.", "Na[Al(OH)4]": "Квадратные скобки комплекса [...] — верный маркер донорно-акцепторной связи."}}, {"id": "t_polarity_sigma", "t": "Полярность молекулы, геометрия и наличие π-связей", "k": "Молекула", "km": "молекулой", "ref": "03.12", "n": 4, "lv3": ["CO2", "SO2", "SO3", "CCl4", "CHCl3", "BF3", "C2H2"], "cols": [{"t": "Полярность молекулы (μ)", "sk": "bond_props", "n": 4, "q": "Полярна или неполярна молекула {x} в целом?", "m": "полярностью молекулы", "mq": "Выберите {k} вещества, характеристика молекул которых — «{v}»:"}, {"t": "Наличие π-связей", "sk": "bond_props", "n": 4, "q": "Есть ли π-связи в молекуле {x}?", "m": "наличием π-связей", "mq": "Выберите {k} вещества, для которых наличие π-связей: «{v}»:"}], "rows": [["CO2", "Неполярная (линейная, 180°)", "Есть (2 π)"], ["C2H2", "Неполярная (линейная, 180°)", "Есть (2 π)"], ["SO3", "Неполярная (треугольник)", "Есть (π-связи)"], ["CH4", "Неполярная (тетраэдр)", "Нет (только σ)"], ["CCl4", "Неполярная (тетраэдр)", "Нет (только σ)"], ["BF3", "Неполярная (треугольник)", "Нет (только σ)"], ["H2O", "Полярная (угловая, 104,5°)", "Нет (только σ)"], ["NH3", "Полярная (пирамида)", "Нет (только σ)"], ["CHCl3", "Полярная (асимметричный тетраэдр)", "Нет (только σ)"], ["SO2", "Полярная (угловая)", "Есть (π-связь)"], ["CO", "Полярная (линейная из разных атомов)", "Есть (2 π)"]], "rw": {"CO2": "Связи C=O полярны, но диполи направлены под 180° и взаимно гасятся → молекула неполярна.", "SO2": "В отличие от CO2, у серы есть неподелённая пара → молекула изогнута (угловая) и полярна.", "CCl4": "Четыре одинаковых атома Cl в вершинах тетраэдра → диполи гасятся (молекула неполярна).", "CHCl3": "Замена одного Cl на H нарушает симметрию → хлороформ полярен."}}, {"id": "t_hbond_map", "t": "Межмолекулярные водородные связи: правило H–F, H–O, H–N", "k": "Вещество", "km": "веществом", "ref": "05.10", "n": 4, "lv3": ["Диметиловый эфир CH3OCH3", "Этаналь CH3CHO", "Ацетон CH3COCH3", "Метилацетат CH3COOCH3", "Триметиламин (CH3)3N", "Фторметан CH3F", "Хлороводород HCl"], "cols": [{"t": "Межмолекулярная Н-связь (между своими молекулами)", "sk": "h_bonds", "n": 4, "q": "Образуются ли водородные связи между молекулами чистого вещества «{x}»?", "m": "способностью образовывать водородные связи", "mq": "Выберите {k} вещества, для которых ответ о межмолекулярной водородной связи: «{v}»:"}], "rows": [["Фтороводород HF", "Да (прямая связь H–F)"], ["Вода H2O", "Да (прямая связь H–O)"], ["Этанол C2H5OH", "Да (прямая связь H–O)"], ["Фенол C6H5OH", "Да (прямая связь H–O)"], ["Уксусная кислота CH3COOH", "Да (прямая связь H–O)"], ["Аммиак NH3", "Да (прямая связь H–N)"], ["Метиламин CH3NH2", "Да (прямая связь H–N)"], ["Диметиламин (CH3)2NH", "Да (прямая связь H–N)"], ["Диметиловый эфир CH3OCH3", "Нет (нет прямой связи H–O/N/F)"], ["Этаналь CH3CHO", "Нет (нет прямой связи H–O/N/F)"], ["Ацетон CH3COCH3", "Нет (нет прямой связи H–O/N/F)"], ["Метилацетат CH3COOCH3", "Нет (нет прямой связи H–O/N/F)"], ["Триметиламин (CH3)3N", "Нет (нет прямой связи H–O/N/F)"], ["Фторметан CH3F", "Нет (нет прямой связи H–O/N/F)"], ["Хлороводород HCl", "Нет (Cl не входит в тройку F, O, N)"], ["Сероводород H2S", "Нет (S не входит в тройку F, O, N)"]], "rw": {"Диметиловый эфир CH3OCH3": "Изомер этанола, но O зажат между двумя углеродами — связи O–H нет.", "Этаналь CH3CHO": "В альдегидной группе –CH=O водород сидит на углероде, а не на кислороде.", "Триметиламин (CH3)3N": "Третичный амин: все три связи азота заняты группами CH3, связи N–H нет.", "Фторметан CH3F": "Водород связан только с углеродом, прямой связи H–F нет."}}, {"id": "t_lattices_map", "t": "Четыре типа кристаллических решёток, аллотропия и свойства", "k": "Вещество", "km": "веществом", "ref": "06.14", "n": 4, "lv3": ["Белый фосфор P4", "Красный фосфор P", "Графит C", "Кварц SiO2", "Сухой лёд CO2", "CrO3", "Al2O3", "H2SO4 (тв.)", "NH4Cl"], "cols": [{"t": "Тип кристаллической решётки", "sk": "lattices", "n": 4, "q": "Какой тип кристаллической решётки имеет вещество «{x}» в курсе ЕГЭ?", "m": "типом кристаллической решётки", "mq": "Выберите {k} вещества, имеющие кристаллическую решётку «{v}»:"}, {"t": "Строение (молекулярное / немолекулярное)", "sk": "lattices", "n": 4, "q": "К какому типу строения относится вещество «{x}»?", "m": "типом строения", "mq": "Выберите {k} вещества со строением «{v}»:"}], "rows": [["Кварц SiO2", "Атомная", "Немолекулярное"], ["Карборунд SiC", "Атомная", "Немолекулярное"], ["Нитрид бора BN", "Атомная", "Немолекулярное"], ["Алмаз C", "Атомная", "Немолекулярное"], ["Графит C", "Атомная", "Немолекулярное"], ["Красный фосфор P", "Атомная", "Немолекулярное"], ["Кремний Si", "Атомная", "Немолекулярное"], ["Белый фосфор P4", "Молекулярная", "Молекулярное"], ["Сухой лёд CO2", "Молекулярная", "Молекулярное"], ["Иод I2", "Молекулярная", "Молекулярное"], ["Сера S8", "Молекулярная", "Молекулярное"], ["H2SO4 (тв.)", "Молекулярная", "Молекулярное"], ["CrO3", "Молекулярная", "Молекулярное"], ["NH4Cl", "Ионная", "Немолекулярное"], ["Al2O3", "Ионная", "Немолекулярное"], ["NaCl", "Ионная", "Немолекулярное"], ["Железо Fe", "Металлическая", "Немолекулярное"]], "rw": {"Белый фосфор P4": "Состоит из тетраэдрических молекул P4 → молекулярная решётка (легкоплавкий, 44 °C).", "Красный фосфор P": "Полимерный ковалентный каркас → атомная решётка (немолекулярное строение).", "Графит C": "В науке слоистая решётка, но в ЕГЭ-4 графит стабильно относят к атомной решётке.", "CrO3": "Высший кислотный оксид Cr(+6): ковалентная полярная связь и молекулярная решётка."}}, {"id": "t_trivial_kim4", "t": "Словарь тривиальных названий для задания № 4 ЕГЭ-2027", "k": "Тривиальное название", "km": "названием", "ref": "08.6", "n": 4, "lv3": ["Кремнезём / кварц", "Карборунд", "Сухой лёд", "Пирит (железный колчедан)", "Нашатырь", "Корунд / глинозём", "Негашёная известь", "Мочевина (карбамид)"], "cols": [{"t": "Химическая формула", "sk": "kim4_filter", "n": 4, "q": "Какая химическая формула соответствует тривиальному названию «{x}»?", "m": "химической формулой"}, {"t": "Тип решётки", "sk": "kim4_filter", "n": 4, "q": "Какой тип кристаллической решётки имеет вещество «{x}»?", "m": "типом кристаллической решётки", "mq": "Выберите {k} вещества, имеющие кристаллическую решётку «{v}»:"}], "rows": [["Кремнезём / кварц", "SiO2", "Атомная"], ["Карборунд", "SiC", "Атомная"], ["Сухой лёд", "CO2", "Молекулярная"], ["Пирит (железный колчедан)", "FeS2", "Ионная"], ["Нашатырь", "NH4Cl", "Ионная"], ["Аммиачная селитра", "NH4NO3", "Ионная"], ["Корунд / глинозём", "Al2O3", "Ионная"], ["Негашёная известь", "CaO", "Ионная"], ["Гашёная известь", "Ca(OH)2", "Ионная"], ["Известняк / мел / мрамор", "CaCO3", "Ионная"], ["Едкое кали", "KOH", "Ионная"], ["Угарный газ", "CO", "Молекулярная"], ["Мочевина (карбамид)", "(NH2)2CO", "Молекулярная"]], "rw": {"Нашатырь": "Твёрдая соль NH4Cl (не путать с нашатырным спиртом NH3·H2O!).", "Пирит (железный колчедан)": "FeS2: ионная решётка, внутри аниона [S–S]^{2−} спрятана ковалентная неполярная связь.", "Негашёная известь": "CaO — только ионная связь (в гашёной Ca(OH)2 добавляется ковалентная полярная O–H)."}}], "rx": [], "seq": [{"id": "sq_eo_scale", "sk": "eo_bonds", "ref": "01.11", "n": 4, "lvl": 2, "q": "Расположите элементы в порядке ВОЗРАСТАНИЯ их электроотрицательности (от самой низкой к самой высокой):", "items": ["Na (щелочной металл)", "Si (кремний, 1,90)", "H (водород, 2,20)", "C (углерод, 2,55)", "N (азот, 3,04)", "O (кислород, 3,44)", "F (фтор, 3,98)"], "why": "Водород (2,20) стоит выше металлов и кремния (1,90), но ниже углерода, азота, кислорода и фтора."}, {"id": "sq_hx_length", "sk": "bond_props", "ref": "03.8", "n": 4, "lvl": 3, "q": "Расположите галогеноводороды в порядке УВЕЛИЧЕНИЯ длины связи H–Гал (и, соответственно, уменьшения её энергии/прочности):", "items": ["HF (самая короткая и прочная)", "HCl", "HBr", "HI (самая длинная и слабая)"], "why": "Сверху вниз по VIIA группе радиус галогена растёт (F < Cl < Br < I), поэтому длина связи растёт, а её энергия падает."}, {"id": "sq_cc_strength", "sk": "bond_props", "ref": "03.5", "n": 4, "lvl": 2, "q": "Расположите связи углерод–углерод в порядке УВЕЛИЧЕНИЯ их энергии (прочности) и уменьшения длины:", "items": ["Одинарная C–C (1 σ; 0,154 нм)", "Двойная C=C (1 σ + 1 π; 0,134 нм)", "Тройная C≡C (1 σ + 2 π; 0,120 нм)"], "why": "С ростом кратности связи атомы притягиваются сильнее: длина связи сокращается, а энергия разрыва растёт."}, {"id": "sq_via_boiling", "sk": "h_bonds", "ref": "05.8", "n": 4, "lvl": 3, "q": "Расположите водородные соединения элементов VIA группы в порядке ВОЗРАСТАНИЯ их температуры кипения (учитывая аномалию водородной связи!):", "items": ["H2S (−60 °C)", "H2Se (−41 °C)", "H2Te (−2 °C)", "H2O (+100 °C — аномалия из-за Н-связей!)"], "why": "От H2S к H2Te растёт молярная масса и силы Ван-дер-Ваальса, а вода H2O резко вырывается вперёд (+100 °C) благодаря прочным межмолекулярным водородным связям."}], "facts": [{"id": "f_eo_bonds", "sk": "eo_bonds", "ref": "01.15", "n": 4, "s": [["Все элементы побочных подгрупп (B-групп) таблицы ФИПИ являются металлами.", "Элементы побочных подгрупп VI–VII групп (Cr, Mn) являются неметаллами.", "Все d-элементы побочных подгрупп — исключительно металлы."], ["В молекуле HF химическая связь является ковалентной полярной.", "Поскольку ΔЭО в HF равно 1,78, фтороводород имеет ионную связь.", "H и F — оба неметаллы; у водорода нет внутренних оболочек, поэтому HF — ковалентная полярная молекула."], ["В силане SiH4 общая электронная пара смещена к водороду (Si^{+4}H^{−1}4).", "В силане SiH4 общая электронная пара смещена к кремнию, как в метане CH4.", "ЭО(H) = 2,20 > ЭО(Si) = 1,90, поэтому в SiH4 отрицательный заряд на водороде."], ["Благородным газам (He, Ne, Ar) в школьной модели ЕГЭ электроотрицательность не приписывают.", "Гелий и неон имеют самую высокую электроотрицательность, превосходящую фтор.", "Оболочка благородных газов уже завершена; самый электроотрицательный элемент — фтор F."]]}, {"id": "f_covalent_dam", "sk": "covalent_dam", "ref": "02.15", "n": 4, "s": [["После образования донорно-акцепторная связь физически неразличима с обменной (в NH4^{+} все 4 связи N–H равноценны).", "В ионе аммония NH4^{+} три связи N–H короткие обменные, а четвёртая (донорно-акцепторная) длиннее и слабее.", "ДАМ — это лишь способ сборки ковалентной связи; после образования все 4 связи N–H одинаковы."], ["В угарном газе CO одна из трёх связей между углеродом и кислородом образована по донорно-акцепторному механизму.", "В углекислом газе CO2 и аммиаке NH3 присутствуют связи по донорно-акцепторному механизму.", "В CO третья связь — ДАМ (O → C); а в CO2 и NH3 все связи только обменные!"], ["В пероксиде натрия Na2O2, пирите FeS2 и карбиде кальция CaC2 есть ковалентная неполярная связь.", "В карбиде алюминия Al4C3 и формиате натрия HCOONa есть ковалентная неполярная связь C–C.", "В Al4C3 отдельные ионы C^{4−}, а в HCOONa всего один атом C — связи C–C в них нет."], ["В комплексных солях с квадратными скобками (Na[Al(OH)4], K2[Zn(OH)4]) всегда есть донорно-акцепторная связь.", "В комплексных солях вроде Na[Al(OH)4] есть только ионная связь без донорно-акцепторного механизма.", "Лиганды (OH^{−}, NH3, CN^{−}) отдают неподелённые пары на пустые орбитали металла-комплексообразователя."]]}, {"id": "f_bond_props", "sk": "bond_props", "ref": "03.12", "n": 4, "s": [["Молекула углекислого газа CO2 неполярна, хотя связи C=O в ней полярны.", "Поскольку связи C=O полярны, молекула CO2 является полярной.", "CO2 — линейная симметричная молекула (180°), диполи связей взаимно гасятся."], ["Молекула сернистого газа SO2 полярна из-за углового строения (на сере есть неподелённая пара).", "Молекулы CO2 и SO2 обе линейны и неполярны.", "У углерода в CO2 нет неподелённой пары (линейная), а у серы в SO2 есть (угловая → полярная)."], ["Любая тройная связь (N≡N, C≡C, C≡O) состоит из 1 σ-связи и 2 π-связей.", "Тройная связь состоит из 3 σ-связей, поэтому она самая прочная.", "Между двумя атомами всегда ровно одна σ-связь, а все дополнительные кратные — π-связи."], ["В ряду HF → HCl → HBr → HI длина связи увеличивается, а её энергия уменьшается.", "В ряду HF → HCl → HBr → HI прочность связи растёт из-за роста массы галогена.", "Радиус галогена растёт сверху вниз → ядра дальше → связь длиннее и слабее."]]}, {"id": "f_ionic_metal", "sk": "ionic_metal", "ref": "04.8", "n": 4, "s": [["В хлориде аммония NH4Cl и хлориде метиламмония CH3NH3Cl есть ионная связь, хотя в них нет атомов металла.", "Ионная связь может возникать исключительно между металлом и неметаллом.", "Сложные катионы NH4^{+} и RNH3^{+} образуют с анионами полноценную ионную связь."], ["Металлическая связь сохраняется даже в жидкой ртути Hg и в сплавах (бронза, латунь).", "В поваренной соли NaCl и оксиде железа Fe2O3 есть металлическая связь, так как там есть атомы металлов.", "Металлическая связь есть только в простых веществах-металлах и сплавах, никогда в солях/оксидах."], ["В этилате натрия C2H5ONa и ацетате натрия CH3COONa одновременно есть ионная, ковалентная полярная и ковалентная неполярная связи.", "В этилате натрия C2H5ONa есть только ионная и ковалентная полярная связи.", "В этильном и ацетильном остатках есть связь C–C (ковалентная неполярная)!"], ["Высшие кислотные оксиды CrO3 и Mn2O7 имеют ковалентную полярную связь и молекулярное строение.", "Все без исключения оксиды металлов (включая CrO3 и Mn2O7) имеют ионную решётку.", "При высоких с.о. (+6, +7) связь металл–кислород становится ковалентной полярной (молекулярная решётка)."]]}, {"id": "f_h_bonds", "sk": "h_bonds", "ref": "05.10", "n": 4, "s": [["Между молекулами диметилового эфира CH3OCH3 и этаналя CH3CHO водородные связи не образуются.", "В диметиловом эфире CH3OCH3 есть и H, и O, поэтому между его молекулами есть водородные связи.", "Нужна прямая ковалентная связь H–O, H–N или H–F; в эфирах и альдегидах водород связан только с C."], ["Первичные (CH3NH2) и вторичные ((CH3)2NH) амины образуют межмолекулярные водородные связи, а третичные ((CH3)3N) — нет.", "Все амины, включая триметиламин (CH3)3N, образуют межмолекулярные водородные связи.", "В третичном амине у азота нет атомов водорода (нет связи N–H)."], ["Уксусная кислота CH3COOH образует прочные димеры за счёт межмолекулярных водородных связей.", "Метилформиат HCOOCH3, как и его изомер CH3COOH, образует водородные связи между своими молекулами.", "В сложном эфире HCOOCH3 нет группы –OH, поэтому межмолекулярных Н-связей нет."], ["В ряду галогенов F2 → Cl2 → Br2 → I2 температура кипения растёт из-за усиления сил Ван-дер-Ваальса с ростом молярной массы.", "Иод I2 — твёрдое вещество при н.у., потому что между его молекулами действуют водородные связи.", "В I2 вообще нет водорода; твёрдое состояние иода объясняется большими силами Ван-дер-Ваальса."]]}, {"id": "f_lattices", "sk": "lattices", "ref": "06.14", "n": 4, "s": [["Белый фосфор P4 имеет молекулярную решётку, а красный и чёрный фосфор — атомную.", "Все аллотропные модификации фосфора имеют атомную кристаллическую решётку.", "Белый фосфор состоит из отдельных тетраэдрических молекул P4 (молекулярная решётка)."], ["Серная (H2SO4), азотная (HNO3) и фосфорная (H3PO4) кислоты имеют молекулярную кристаллическую решётку.", "Серная и фосфорная кислоты — сильные/средние электролиты, поэтому в твёрдом виде они имеют ионную решётку.", "В твёрдом состоянии кислоты состоят из нейтральных молекул (молекулярное строение); на ионы они распадаются лишь в воде."], ["Оксид кремния(IV) SiO2 имеет атомную решётку, а углекислый газ CO2 — молекулярную.", "Поскольку C и Si стоят в одной группе, CO2 и SiO2 имеют одинаковую атомную кристаллическую решётку.", "У углерода образуются двойные связи O=C=O (отдельные молекулы), а у кремния — 3D-каркас из одинарных Si–O."], ["Графит в заданиях № 4 ЕГЭ стабильно относят к атомной кристаллической решётке (немолекулярное строение).", "Графит мягкий и пишет на бумаге, поэтому в ЕГЭ его относят к молекулярной решётке.", "Несмотря на слоистость, в ЕГЭ-4 графит всегда относят к атомной решётке."]]}, {"id": "f_crystal_props", "sk": "crystal_props", "ref": "07.7", "n": 4, "s": [["Твёрдые ионные кристаллы (например, NaCl) хрупки и не проводят электрический ток, но их расплавы и водные растворы ток проводят.", "Твёрдая поваренная соль NaCl хорошо проводит электрический ток, так как состоит из ионов.", "В твёрдом кристалле ионы закреплены в узлах и не двигаются; подвижность появляется только в расплаве или растворе."], ["Наличие резкого запаха и лёгкая возгонка у твёрдого вещества (иод, камфора, фенол) указывают на молекулярную кристаллическую решётку.", "Запах твёрдого вещества характерен для ионных и атомных кристаллов.", "Отрыв частиц с поверхности при 20 °C возможен только при слабых межмолекулярных силах."], ["Атомные кристаллы (алмаз, SiO2, SiC) имеют очень высокую температуру плавления и практически нерастворимы ни в воде, ни в органике.", "Атомные кристаллы, такие как SiO2 и SiC, хорошо растворяются в воде, как соли.", "Прочный ковалентный 3D-каркас не разрушается молекулами воды."], ["Пластичность и ковкость металлов объясняются тем, что при сдвиге слоёв «электронный газ» не разрывается и удерживает катионы вместе.", "Ионные кристаллы так же ковки и пластичны, как металлы.", "При сдвиге слоёв в ионном кристалле одноимённые заряды оказываются друг напротив друга и раскалывают кристалл."]]}, {"id": "f_kim4_filter", "sk": "kim4_filter", "ref": "08.6", "n": 4, "s": [["В задании № 4 ЕГЭ-2027 порядок записи двух цифр в ответе значения не имеет (35 и 53 равноценны), а максимальный балл равен 1.", "В задании № 4 порядок цифр строго фиксирован и за одну верную цифру ставят 1 балл из 2.", "Задание № 4 оценивается 1 первичным баллом; ошибка хотя бы в одной цифре даёт 0 баллов, порядок не важен."], ["Нашатырь — это твёрдый хлорид аммония NH4Cl (ионная решётка, есть ДАМ), а не нашатырный спирт NH3·H2O.", "Нашатырь имеет формулу NH3 и молекулярную кристаллическую решётку.", "В КИМ № 4 «нашатырь» всегда означает соль NH4Cl."], ["В негашёной извести CaO есть только ионная связь, а в гашёной извести Ca(OH)2 — ионная и ковалентная полярная.", "И в негашёной (CaO), и в гашёной (Ca(OH)2) извести есть ковалентная полярная связь.", "CaO — бинарный оксид (только ионная связь), а в Ca(OH)2 есть группа O–H (ковалентная полярная)."], ["Кремнезём (SiO2) и карборунд (SiC) имеют атомную решётку и ковалентную полярную связь.", "Кремнезём (SiO2) и сухой лёд (CO2) оба имеют атомную решётку.", "Сухой лёд — это твёрдый CO2 с молекулярной решёткой!"]]}], "calc": [], "tasks": [{"id": "t01_demo2027", "sk": "kim4_filter", "ref": "08.9", "n": 4, "lvl": 2, "type": "multi", "q": "Демоверсия ФИПИ ЕГЭ-2027 (№ 4). Из предложенного перечня выберите ДВА вещества с ковалентной полярной химической связью, которые имеют ионную кристаллическую решётку:", "o": ["хлорид кальция", "оксид фосфора(V)", "этилат натрия", "аммиак", "гидроксид калия"], "a": [2, 4], "ex": "Фильтр 1 (ионная решётка): отбрасываем молекулярные P2O5 (2) и NH3 (4); остаются CaCl2, C2H5ONa, KOH. Фильтр 2 (ковалентная полярная связь): в бинарном CaCl2 только ионная связь; в этилате натрия C2H5ONa (C–H, C–O) и KOH (O–H) есть ковалентная полярная связь. Ответ: 35."}, {"id": "t02_dam_nonmol", "sk": "covalent_dam", "ref": "08.11", "n": 4, "lvl": 3, "type": "multi", "q": "Выберите ДВА вещества НЕМОЛЕКУЛЯРНОГО строения, в которых есть связь, образованная по донорно-акцепторному механизму:", "o": ["угарный газ", "хлорид аммония", "азотная кислота", "тетрагидроксоалюминат натрия", "аммиак"], "a": [1, 3], "ex": "Фильтр 1 (немолекулярное строение): CO, HNO3 и NH3 — молекулярные (отбрасываем 1, 3, 5, хотя в CO и HNO3 есть ДАМ!). Остаются ионные соли NH4Cl (2) и Na[Al(OH)4] (4) — в обеих есть ДАМ. Ответ: 24."}, {"id": "t03_hidden_nonpolar_ionic", "sk": "covalent_dam", "ref": "08.13", "n": 4, "lvl": 3, "type": "multi", "q": "Выберите ДВА вещества ионного строения, в которых присутствует ковалентная неполярная связь:", "o": ["пероксид водорода", "пероксид натрия", "формиат натрия", "пирит", "хлорид натрия"], "a": [1, 3], "ex": "Фильтр 1 (ионное строение): H2O2 — молекулярное (отбрасываем 1). Фильтр 2 (ковалентная неполярная): в Na2O2 есть O–O (2), в пирите FeS2 есть S–S (4); в формиате HCOONa всего 1 атом C (связи C–C нет!), в NaCl только ионная связь. Ответ: 24."}, {"id": "t04_hbond_mol", "sk": "h_bonds", "ref": "08.15", "n": 4, "lvl": 3, "type": "multi", "q": "Выберите ДВА вещества молекулярного строения, между молекулами которых образуются водородные связи:", "o": ["диметиловый эфир", "этаналь", "фтороводород", "триметиламин", "уксусная кислота"], "a": [2, 4], "ex": "Все 5 веществ молекулярные. Проверяем правило прямой связи H–F, H–O, H–N: в CH3OCH3, CH3CHO и (CH3)3N водород связан только с углеродом (ловушки!). Прямая связь есть в HF (3) и CH3COOH (5). Ответ: 35."}, {"id": "t05_atomic_polar", "sk": "lattices", "ref": "08.17", "n": 4, "lvl": 2, "type": "multi", "q": "Выберите ДВА вещества с атомной кристаллической решёткой и ковалентной полярной связью:", "o": ["кремнезём", "сухой лёд", "алмаз", "карборунд", "белый фосфор"], "a": [0, 3], "ex": "Фильтр 1 (атомная решётка): сухой лёд CO2 и белый фосфор P4 — молекулярные (отбрасываем 2 и 5). Остаются SiO2 (1), алмаз C (3), SiC (4). Фильтр 2 (ковалентная полярная): в алмазе связи C–C неполярные; в SiO2 и SiC — полярные. Ответ: 14."}, {"id": "t06_ionic_no_metal", "sk": "ionic_metal", "ref": "04.4", "n": 4, "lvl": 3, "type": "multi", "q": "Выберите ДВА вещества, которые имеют ионную кристаллическую решётку, но НЕ содержат атомов металла:", "o": ["хлорид метиламмония", "аммиак", "нитрат аммония", "азотная кислота", "оксид кремния(IV)"], "a": [0, 2], "ex": "Соли аминов [CH3NH3]Cl (1) и соли аммония NH4NO3 (3) не содержат металлов, но построены из катионов и анионов → ионная решётка. NH3 и HNO3 — молекулярные, SiO2 — атомная. Ответ: 13."}, {"id": "t07_three_bonds_salt", "sk": "ionic_metal", "ref": "04.15", "n": 4, "lvl": 3, "type": "multi", "q": "Выберите ДВА вещества, в которых одновременно присутствуют ионная, ковалентная полярная и ковалентная неполярная связи:", "o": ["метилат натрия", "ацетат натрия", "пероксид натрия", "фенолят калия", "формиат калия"], "a": [1, 3], "ex": "В ацетате натрия CH3COONa (2) и феноляте калия C6H5OK (4) есть ионная (O^{−}···M^{+}), КПС (C–H, C–O) и КНС (C–C). В CH3ONa и HCOOK всего 1 атом C (нет КНС); в Na2O2 есть ионная и O–O, но нет КПС! Ответ: 24."}, {"id": "t08_only_ionic", "sk": "ionic_metal", "ref": "04.8", "n": 4, "lvl": 2, "type": "multi", "q": "Выберите ДВА вещества, в которых присутствует ТОЛЬКО ионная химическая связь:", "o": ["негашёная известь", "гашёная известь", "карбид алюминия", "карбид кальция", "пирит"], "a": [0, 2], "ex": "Негашёная известь CaO (1) и метанид Al4C3 (3) состоят из одноатомных ионов → только ионная связь. В Ca(OH)2 есть КПС (O–H), в CaC2 есть КНС (C≡C), в FeS2 есть КНС (S–S). Ответ: 13."}, {"id": "t09_dam_mol", "sk": "covalent_dam", "ref": "02.15", "n": 4, "lvl": 3, "type": "multi", "q": "Выберите ДВА вещества МОЛЕКУЛЯРНОГО строения, в которых есть связь, образованная по донорно-акцепторному механизму:", "o": ["угарный газ", "нитрат калия", "озон", "углекислый газ", "хлорид аммония"], "a": [0, 2], "ex": "Фильтр 1 (молекулярное строение): отбрасываем ионные KNO3 (2) и NH4Cl (5). Остаются CO (1), O3 (3) и CO2 (4). Фильтр 2 (ДАМ): в CO и O3 есть ДАМ, а в CO2 все связи обменные. Ответ: 13."}, {"id": "t10_polar_bonds_nonpolar_mol", "sk": "bond_props", "ref": "03.12", "n": 4, "lvl": 3, "type": "multi", "q": "Выберите ДВА вещества с ковалентной полярной связью, молекулы которых НЕПОЛЯРНЫ:", "o": ["тетрахлорметан", "хлороформ", "сернистый газ", "трифторид бора", "аммиак"], "a": [0, 3], "ex": "CCl4 (1 — правильный тетраэдр) и BF3 (4 — правильный плоский треугольник) полностью симметричны: диполи полярных связей взаимно гасятся (μ = 0). CHCl3, SO2 и NH3 полярны. Ответ: 14."}, {"id": "t11_allotropy_mol", "sk": "lattices", "ref": "06.14", "n": 4, "lvl": 3, "type": "multi", "q": "Выберите ДВА простых вещества с МОЛЕКУЛЯРНОЙ кристаллической решёткой:", "o": ["белый фосфор", "красный фосфор", "графит", "кристаллическая сера", "кремний"], "a": [0, 3], "ex": "Белый фосфор P4 (1) и кристаллическая сера S8 (4) состоят из отдельных молекул → молекулярная решётка. Красный фосфор, графит и кремний имеют атомную решётку. Ответ: 14."}, {"id": "t12_oxides_mol_vs_ionic", "sk": "lattices", "ref": "06.17", "n": 4, "lvl": 3, "type": "multi", "q": "Выберите ДВА оксида, которые имеют МОЛЕКУЛЯРНУЮ кристаллическую решётку:", "o": ["оксид кремния(IV)", "оксид хрома(VI)", "оксид хрома(III)", "оксид марганца(VII)", "оксид алюминия"], "a": [1, 3], "ex": "Высшие кислотные оксиды CrO3 (2) и Mn2O7 (4) имеют ковалентную полярную связь и молекулярную решётку. SiO2 — атомная решётка; Cr2O3 и Al2O3 в модели ЕГЭ-4 — ионная решётка. Ответ: 24."}, {"id": "t13_metallic_bond", "sk": "ionic_metal", "ref": "04.13", "n": 4, "lvl": 2, "type": "multi", "q": "Выберите ДВА вещества (или материала), в которых присутствует металлическая химическая связь:", "o": ["хлорид натрия", "бронза", "оксид железа(III)", "жидкая ртуть", "гидроксид калия"], "a": [1, 3], "ex": "Металлическая связь есть только в простых веществах-металлах (в т.ч. жидкая ртуть Hg — 4) и сплавах (бронза — 2). В NaCl, Fe2O3 и KOH связь ионная. Ответ: 24."}, {"id": "t14_hbond_amines", "sk": "h_bonds", "ref": "05.10", "n": 4, "lvl": 3, "type": "multi", "q": "Выберите ДВА вещества, между молекулами которых НЕ образуются водородные связи:", "o": ["метиламин", "триметиламин", "фенол", "ацетон", "глицерин"], "a": [1, 3], "ex": "В триметиламине (CH3)3N (2) нет связи N–H, а в ацетоне CH3COCH3 (4) нет связи O–H → межмолекулярных водородных связей нет. В CH3NH2, C6H5OH и глицерине они есть. Ответ: 24."}, {"id": "t15_hbond_inorg", "sk": "h_bonds", "ref": "05.10", "n": 4, "lvl": 2, "type": "multi", "q": "Выберите ДВА неорганических вещества, между молекулами которых образуются водородные связи:", "o": ["сероводород", "аммиак", "хлороводород", "пероксид водорода", "силан"], "a": [1, 3], "ex": "Прямая связь H–N есть в NH3 (2), а прямая связь H–O есть в H2O2 (4). В H2S, HCl и SiH4 нет атомов F, O или N. Ответ: 24."}, {"id": "t16_nonmol_all", "sk": "lattices", "ref": "06.18", "n": 4, "lvl": 2, "type": "multi", "q": "Выберите ДВА вещества НЕМОЛЕКУЛЯРНОГО строения:", "o": ["серная кислота", "нитрид бора", "глюкоза", "аммиачная селитра", "иод"], "a": [1, 3], "ex": "Нитрид бора BN (2 — атомная решётка) и аммиачная селитра NH4NO3 (4 — ионная решётка) имеют немолекулярное строение. H2SO4, глюкоза и I2 — молекулярного строения. Ответ: 24."}, {"id": "t17_props_melt_conduct", "sk": "crystal_props", "ref": "07.12", "n": 4, "lvl": 3, "type": "multi", "q": "Выберите ДВА вещества, которые НЕ проводят электрический ток в твёрдом состоянии, но хорошо проводят его в расплаве:", "o": ["кварц", "хлорид калия", "медь", "гидроксид натрия", "иод"], "a": [1, 3], "ex": "Это точный признак ИОННОЙ решётки: в твёрдом виде ионы закреплены, в расплаве подвижны → KCl (2) и NaOH (4). Медь (3) проводит ток уже в твёрдом виде; SiO2 (1) и I2 (5) не проводят и в расплаве. Ответ: 24."}, {"id": "t18_props_volatile", "sk": "crystal_props", "ref": "07.10", "n": 4, "lvl": 2, "type": "multi", "q": "Выберите ДВА твёрдых вещества, которые имеют низкую температуру плавления, летучи и обладают запахом:", "o": ["фенол", "карборунд", "поваренная соль", "кристаллический иод", "корунд"], "a": [0, 3], "ex": "Низкая t_пл, летучесть и запах — признаки МОЛЕКУЛЯРНОЙ решётки: фенол C6H5OH (1) и иод I2 (4). SiC (атомная), NaCl и Al2O3 (ионные) тугоплавки и не пахнут. Ответ: 14."}, {"id": "t19_props_solid_conduct", "sk": "crystal_props", "ref": "07.8", "n": 4, "lvl": 3, "type": "multi", "q": "Выберите ДВА вещества, которые проводят электрический ток в ТВЁРДОМ состоянии:", "o": ["хлорид натрия", "графит", "алмаз", "алюминий", "сахароза"], "a": [1, 3], "ex": "В твёрдом состоянии ток проводят металлы (алюминий Al — 4) и уникальное исключение среди неметаллов — графит (2, за счёт делокализованных электронов между слоями). Твёрдый NaCl, алмаз и сахароза — изоляторы. Ответ: 24."}, {"id": "t20_props_hard_insoluble", "sk": "crystal_props", "ref": "07.7", "n": 4, "lvl": 2, "type": "multi", "q": "Выберите ДВА вещества, обладающих очень высокой твёрдостью, тугоплавкостью и практической нерастворимостью в воде:", "o": ["карборунд", "сухой лёд", "поваренная соль", "алмаз", "белый фосфор"], "a": [0, 3], "ex": "Высочайшая твёрдость + тугоплавкость + нерастворимость — паспорт АТОМНОЙ решётки: карборунд SiC (1) и алмаз C (4). CO2 и P4 — молекулярные, NaCl — ионная (хорошо растворим). Ответ: 14."}, {"id": "t21_pi_bonds", "sk": "bond_props", "ref": "03.15", "n": 4, "lvl": 2, "type": "multi", "q": "Выберите ДВА вещества, в молекулах которых присутствуют π-связи:", "o": ["метан", "углекислый газ", "вода", "ацетилен", "аммиак"], "a": [1, 3], "ex": "π-связи есть только в кратных (двойных и тройных) связях: в CO2 (O=C=O, 2 π-связи) и ацетилене C2H2 (H–C≡C–H, 2 π-связи). В CH4, H2O и NH3 все связи одинарные (только σ). Ответ: 24."}, {"id": "t22_two_pi_bonds", "sk": "bond_props", "ref": "03.5", "n": 4, "lvl": 3, "type": "multi", "q": "Выберите ДВА вещества, в каждой молекуле которых содержится ровно ДВЕ π-связи:", "o": ["азот", "кислород", "угарный газ", "этилен", "хлор"], "a": [0, 2], "ex": "Тройная связь содержит 1 σ + 2 π: в азоте N≡N (1) и угарном газе C≡O (3) ровно по две π-связи! В O=O и CH2=CH2 по 1 π-связи, в Cl–Cl их 0. Ответ: 13."}, {"id": "t23_same_lattice_atomic", "sk": "lattices", "ref": "06.8", "n": 4, "lvl": 2, "type": "multi", "q": "Выберите ДВА вещества, которые имеют такую же кристаллическую решётку, как и алмаз:", "o": ["белый фосфор", "красный фосфор", "кремнезём", "сухой лёд", "сера"], "a": [1, 2], "ex": "У алмаза атомная кристаллическая решётка. Из списка её имеют красный фосфор (2) и кремнезём SiO2 (3). P4, CO2 и S8 — молекулярные. Ответ: 23."}, {"id": "t24_nonpolar_mol_complex", "sk": "covalent_dam", "ref": "02.7", "n": 4, "lvl": 3, "type": "multi", "q": "Выберите ДВА сложных вещества МОЛЕКУЛЯРНОГО строения, в которых есть ковалентная неполярная связь:", "o": ["гидразин", "пероксид бария", "щавелевая кислота", "метан", "карбид кальция"], "a": [0, 2], "ex": "Фильтр 1 (молекулярное строение): отбрасываем ионные BaO2 (2) и CaC2 (5). Фильтр 2 (ковалентная неполярная): в гидразине H2N–NH2 (1) есть связь N–N, в щавелевой кислоте HOOC–COOH (3) есть связь C–C. В метане CH4 только C–H. Ответ: 13."}, {"id": "t25_complex_dam_salt", "sk": "covalent_dam", "ref": "04.15", "n": 4, "lvl": 3, "type": "multi", "q": "Выберите ДВА вещества, в которых одновременно присутствуют ионная связь и связь, образованная по донорно-акцепторному механизму:", "o": ["тетрагидроксоцинкат калия", "гидроксид цинка", "угарный газ", "сульфат аммония", "азотная кислота"], "a": [0, 3], "ex": "Фильтр 1 (ионная связь): отбрасываем молекулярные CO (3) и HNO3 (5). Фильтр 2 (ДАМ): в K2[Zn(OH)4] (1) и (NH4)2SO4 (4) есть и ионная связь, и ДАМ; в Zn(OH)2 ДАМ нет. Ответ: 14."}, {"id": "t26_trivial_ionic_polar", "sk": "kim4_filter", "ref": "08.6", "n": 4, "lvl": 2, "type": "multi", "q": "Выберите ДВА вещества, имеющих ионную кристаллическую решётку и ковалентную полярную связь:", "o": ["известняк", "негашёная известь", "едкий натр", "корунд", "мочевина"], "a": [0, 2], "ex": "Переводим названия: известняк CaCO3 (1 — ион. + КПС C–O), негашёная известь CaO (2 — только ионная), едкий натр NaOH (3 — ион. + КПС O–H), корунд Al2O3 (4 — только ионная), мочевина (NH2)2CO (5 — молекулярная). Ответ: 13."}, {"id": "t27_crystal_hydrate", "sk": "ionic_metal", "ref": "04.8", "n": 4, "lvl": 3, "type": "multi", "q": "Выберите ДВА вещества с ионной решёткой, в которых присутствуют и ковалентная полярная, и водородная связи (кристаллогидраты):", "o": ["медный купорос", "хлорид натрия", "гипс", "этанол", "пирит"], "a": [0, 2], "ex": "Медный купорос CuSO4·5H2O (1) и гипс CaSO4·2H2O (3) — кристаллогидраты: ионная решётка, ковалентные полярные связи и водородные связи с кристаллизационной водой. Этанол — молекулярный; в NaCl и FeS2 воды нет. Ответ: 13."}, {"id": "t28_eo_hydrides", "sk": "eo_bonds", "ref": "01.11", "n": 4, "lvl": 3, "type": "multi", "q": "Выберите ДВА соединения, в которых химическая связь ковалентная полярная, а общая электронная пара смещена К УГЛЕРОДУ или КИСЛОРОДУ (не к водороду):", "o": ["силан", "метан", "гидрид кальция", "вода", "гидрид натрия"], "a": [1, 3], "ex": "Гидриды CaH2 и NaH — ионные (и пара у H^{−}); в силане SiH4 пара смещена к H (ЭО H > Si). В метане CH4 (2) и воде H2O (4) связь ковалентная полярная, и пара смещена к более электроотрицательным C и O. Ответ: 24."}, {"id": "t29_hbond_isomers", "sk": "h_bonds", "ref": "05.11", "n": 4, "lvl": 3, "type": "multi", "q": "Выберите ДВА вещества с молекулярной решёткой, между молекулами которых образуются водородные связи (не попадись на изомеры!):", "o": ["метилформиат", "муравьиная кислота", "диэтиловый эфир", "бутанол-1", "пропаналь"], "a": [1, 3], "ex": "В муравьиной кислоте HCOOH (2) и бутаноле-1 C4H9OH (4) есть прямая связь –O–H → водородные связи есть. В сложном эфире HCOOCH3, простом эфире (C2H5)2O и альдегиде C2H5CHO связи O–H нет. Ответ: 24."}, {"id": "t30_same_bond_nonpolar", "sk": "covalent_dam", "ref": "02.7", "n": 4, "lvl": 2, "type": "multi", "q": "Выберите ДВА вещества, в которых присутствует ТОЛЬКО ковалентная неполярная связь:", "o": ["алмаз", "пероксид водорода", "белый фосфор", "пероксид натрия", "этан"], "a": [0, 2], "ex": "Только ковалентная неполярная связь бывает в простых веществах-неметаллах: алмаз C (1) и белый фосфор P4 (3). В H2O2 и C2H6 есть также КПС, а в Na2O2 — ионная связь. Ответ: 13."}, {"id": "t31_match_lattices", "sk": "lattices", "ref": "06.14", "n": 4, "lvl": 3, "type": "match", "q": "Установите соответствие между веществом и типом его кристаллической решётки в модели ЕГЭ:", "left": ["А) карборунд (SiC)", "Б) сухой лёд (CO2)", "В) нашатырь (NH4Cl)", "Г) бронза (сплав Cu и Sn)"], "right": ["ионная", "атомная", "молекулярная", "металлическая"], "a": [1, 2, 0, 3], "ex": "SiC — атомная (2); CO2 — молекулярная (3); NH4Cl — ионная (1); бронза — металлическая (4)."}, {"id": "t32_match_props", "sk": "crystal_props", "ref": "07.7", "n": 4, "lvl": 2, "type": "match", "q": "Установите соответствие между описанием физических свойств и типом кристаллической решётки:", "left": ["А) хрупкое, тугоплавкое, ток проводит только в расплаве и водном растворе", "Б) ковкое, пластичное, блестит, проводит ток в твёрдом состоянии", "В) легкоплавкое, летучее, имеет резкий запах, ток не проводит", "Г) сверхтвёрдое, t_пл > 1700 °C, нерастворимо в воде, изолятор"], "right": ["ионная", "металлическая", "молекулярная", "атомная"], "a": [0, 1, 2, 3], "ex": "А — ионная (NaCl); Б — металлическая (Cu); В — молекулярная (I2); Г — атомная (SiO2, алмаз)."}, {"id": "t33_match_bonds", "sk": "ionic_metal", "ref": "04.8", "n": 4, "lvl": 3, "type": "match", "q": "Установите соответствие между формулой вещества и полным набором видов химической связи в нём:", "left": ["А) CaCl2", "Б) KOH", "В) C2H5ONa", "Г) Na2O2"], "right": ["только ионная", "ионная и ковалентная полярная", "ионная, ковалентная полярная и ковалентная неполярная", "ионная и ковалентная неполярная"], "a": [0, 1, 2, 3], "ex": "CaCl2 — только ионная; KOH — ионная + КПС (O–H); C2H5ONa — ионная + КПС (C–H, C–O) + КНС (C–C); Na2O2 — ионная + КНС (O–O)."}, {"id": "t34_one_hf_strength", "sk": "bond_props", "ref": "03.8", "n": 4, "lvl": 2, "type": "one", "q": "Почему в ряду HF → HCl → HBr → HI энергия связи уменьшается?", "o": ["Растёт радиус атома галогена, поэтому связь удлиняется и становится менее прочной", "Увеличивается кратность связи от одинарной к тройной", "Уменьшается число электронных слоёв у галогена", "Связь постепенно переходит из ковалентной в металлическую"], "a": 0, "ex": "При движении вниз по VIIA группе растёт радиус атома галогена → увеличивается длина связи H–Гал → падает её энергия (прочность).", "d": {"1": "Во всех галогеноводородах связь одинарная (1 σ).", "2": "Число электронных слоёв вниз по группе растёт, а не уменьшается.", "3": "Все галогеноводороды имеют ковалентную полярную связь."}}, {"id": "t35_one_co2_sio2", "sk": "lattices", "ref": "06.9", "n": 4, "lvl": 3, "type": "one", "q": "Почему углекислый газ CO2 при н.у. — газ, а его аналог по группе SiO2 (кварц) — тугоплавкий кристалл (t_пл ≈ 1713 °C)?", "o": ["Углерод образует прочные двойные π-связи O=C=O (отдельные молекулы), а крупный кремний сшивается 4 одинарными связями Si–O в непрерывный атомный каркас", "В SiO2 связь ионная, а в CO2 — ковалентная неполярная", "Молекулы SiO2 удерживаются прочными водородными связями", "У кремния выше электроотрицательность, чем у углерода"], "a": 0, "ex": "Атом C (2-й период) легко образует π-связи O=C=O (молекулярная решётка), а атом Si (3-й период) образует 4 одинарные σ-связи Si–O с четырьмя соседями (атомная решётка).", "d": {"1": "В обоих веществах связь ковалентная полярная.", "2": "В SiO2 нет водорода и вообще нет отдельных молекул.", "3": "ЭО(C) = 2,55 выше, чем ЭО(Si) = 1,90."}}, {"id": "t36_one_graphite_trap", "sk": "crystal_props", "ref": "06.15", "n": 4, "lvl": 3, "type": "one", "q": "К какому типу кристаллической решётки относят графит в задании № 4 ЕГЭ, и чем объясняется его мягкость?", "o": ["В ЕГЭ-4 относят к атомной решётке (немолекулярное строение); мягкость объясняется слабым притяжением между параллельными атомными слоями", "К молекулярной решётке, потому что он легко оставляет след на бумаге", "К металлической решётке, потому что он проводит электрический ток", "К ионной решётке, потому что он тугоплавок"], "a": 0, "ex": "Внутри слоёв атомы C связаны прочными ковалентными связями, а между слоями действуют слабые силы Ван-дер-Ваальса (слои легко сдвигаются). В ЕГЭ-4 графит стабильно относят к атомной решётке.", "d": {"1": "Мягкость графита связана со сдвигом слоёв, но в ЕГЭ он относится к атомной решётке.", "2": "Углерод — неметалл, металлической решётки у него нет.", "3": "В графите нет ионов."}}, {"id": "t37_short_carborundum", "sk": "kim4_filter", "ref": "08.6", "n": 4, "lvl": 2, "type": "short", "q": "Запишите химическую формулу карборунда (вещества с атомной кристаллической решёткой и ковалентной полярной связью):", "a": ["SiC"], "ex": "Карборунд — это карбид кремния SiC, один из трёх главных сложных кристаллов с атомной решёткой в ЕГЭ (наряду с SiO2 и BN)."}, {"id": "t38_short_pyrite", "sk": "kim4_filter", "ref": "08.6", "n": 4, "lvl": 2, "type": "short", "q": "Запишите химическую формулу пирита (железного колчедана) — ионного вещества со скрытой ковалентной неполярной связью S–S:", "a": ["FeS2"], "ex": "Пирит имеет формулу FeS2 (Fe^{2+}[S–S]^{2−}), в отличие от обычного сульфида FeS, где связи S–S нет."}], "subjectSlug": "chemistry", "_kim": {"4": {"b": 1, "l": "Б"}}, "_kon": {"01": {"t": "Модуль 01. Зачем атомы соединяются: электроотрицательность и карта таблицы ФИПИ", "x": "Любая химическая связь возникает по одной причине: атомы перестраивают свои внешние электроны так, чтобы достичь более устойчивого состояния с меньшей энергией. А то, какой именно вид связи получится — ковалентная, ионная или металлическая — определяет разница в [[Электроотрицательность|электроотрицательности]] (ЭО) между атомами."}, "01.1": {"t": "Модуль 01 · Главная мысль.", "x": "Любая химическая связь возникает по одной причине: атомы перестраивают свои внешние электроны так, чтобы достичь более устойчивого состояния с меньшей энергией. А то, какой именно вид связи получится — ковалентная, ионная или металлическая — определяет разница в [[Электроотрицательность|электроотрицательности]] (ЭО) между атомами."}, "01.11": {"t": "Модуль 01 · Ловушка ЕГЭ: водород и его соседи по ЭО", "x": "**Особое место водорода H:** в таблице ФИПИ водород стоит в I группе (а в скобках дублируется в VII), но это **неметалл**! По электроотрицательности (≈ 2,20) он стоит между бором/фосфором и углеродом: выше, чем у Si (1,90) и всех металлов, примерно равен P (2,19), но **ниже**, чем у C (2,55), S (2,58), N (3,04), Cl (3,16), O (3,44) и F (3,98). Поэтому в CH4 электроны смещены к углероду (C^{−4}H^{+1}4), а в SiH4 и NaH — к водороду (Na^{+1}H^{−1})."}, "01.15": {"t": "Модуль 01 · 3. Единая шкала: от ковалентной неполярной к ионной связи", "x": "• **Ковалентная неполярная** — Какие частицы связывает: Одинаковые неметаллы; Что происходит с электронами: Общая пара ровно посередине; Примеры: H2, O2, N2, O–O в H2O2, C–C в этане\n• **Ковалентная полярная** — Какие частицы связывает: Разные неметаллы; Что происходит с электронами: Общая пара смещена к атому с большей ЭО; Примеры: HCl, H2O, NH3, CO2, O–H в KOH\n• **Ионная** — Какие частицы связывает: Катионы и анионы (типично Ме + НеМе, а также NH4^{+} + анион); Что происходит с электронами: Полный переход электронов, притяжение ионов; Примеры: NaCl, CaO, KOH, NH4Cl, C2H5ONa\n• **Металлическая** — Какие частицы связывает: Катионы/атомы металлов и свободные электроны; Что происходит с электронами: Обобществлённый «электронный газ»; Примеры: Fe, Cu, Na, Hg, бронза, латунь…"}, "02": {"t": "Модуль 02. Ковалентная связь: скрытые неполярные связи и донорно-акцепторный механизм", "x": "[[Ковалентная связь]] образуется между атомами неметаллов за счёт общих электронных пар. Она бывает **неполярной** (одинаковые неметаллы — в том числе внутри сложных веществ!) и **полярной** (разные неметаллы), а по способу сборки делится на **обменный** и **донорно-акцепторный** механизмы."}, "02.1": {"t": "Модуль 02 · Главная мысль.", "x": "[[Ковалентная связь]] образуется между атомами неметаллов за счёт общих электронных пар. Она бывает **неполярной** (одинаковые неметаллы — в том числе внутри сложных веществ!) и **полярной** (разные неметаллы), а по способу сборки делится на **обменный** и **донорно-акцепторный** механизмы."}, "02.7": {"t": "Модуль 02 · 2. Скрытые ковалентные неполярные связи в сложных веществах", "x": "• **Пероксиды и надпероксиды (H2O2, Na2O2, BaO2, KO2)** — Структурный фрагмент: H–O–O–H, Na^{+}[O–O]^{2−}Na^{+}; Где спрятана неполярная связь: Кислородный мостик O–O; Какие ещё связи есть: В H2O2 — ковал. полярная; в Na2O2, KO2 — ионная\n• **Пирит (FeS2)** — Структурный фрагмент: Fe^{2+}[S–S]^{2−}; Где спрятана неполярная связь: Дисульфидный мостик S–S; Какие ещё связи есть: Ионная между Fe^{2+} и S2^{2−} (в обычном FeS связи S–S нет!)\n• **Карбид кальция (CaC2)** — Структурный фрагмент: Ca^{2+}[C≡C]^{2−}; Где спрятана неполярная связь: Тройная связь C≡C; Какие ещё связи есть: Ионная между Ca^{2+} и C2^{2−}\n• **Гидразин (N2H4)** — Структурный фрагмент: H2N–NH2; Где спрятана неполярная связь: Связь N–N; Какие ещё связи есть: Ковалентные полярные N–H…"}, "02.8": {"t": "Модуль 02 · Ловушка ЕГЭ: формиат vs ацетат и CaC2 vs Al4C3", "x": "**Две главные ловушки по скрытым неполярным связям:** 1) **Один углерод vs два углерода:** в ацетате CH3COONa и этилате C2H5ONa есть связь C–C (ковалентная неполярная), а в формиате HCOONa, метилате CH3ONa, метане CH4, метаноле CH3OH и формальдегиде HCHO всего **один атом углерода** — связи C–C там **НЕТ**! 2) **Карбиды CaC2 vs Al4C3 vs SiC:** в ацетилениде CaC2 есть неполярная связь C≡C; в метаниде **Al4C3** стоят отдельные ионы Al^{3+} и C^{4−} — ковалентной неполярной связи там **НЕТ** (только ионная, как в Na2O и FeS); а карбид кремния **SiC** (карборунд) имеет ковалентную полярную связь и атомную решётку."}, "02.12": {"t": "Модуль 02 · Почему все 4 связи в ионе аммония одинаковы?", "x": "Донорно-акцепторный механизм — это **способ образования ковалентной связи**, а не отдельный пятый вид связи. После образования электроны «забывают», кто их принёс: в ионе NH4^{+} все 4 связи N–H имеют одинаковую длину и энергию (форма тетраэдра)."}, "02.15": {"t": "Модуль 02 · 4. Главный список ЕГЭ: где есть донорно-акцепторная связь", "x": "• **Ион аммония NH4^{+} и **все соли аммония** (NH4Cl, NH4NO3, (NH4)2SO4, CH3COONH4)** — Донор пары: Азот N в NH3; Акцептор орбитали: Катион H^{+} (пустая 1s); Что помнить на ЕГЭ: Самый частый ответ в № 4! Плюс ионная связь с анионом.\n• ****Соли аминов** ([CH3NH3]Cl, [C6H5NH3]Cl)** — Донор пары: Азот N аминогруппы; Акцептор орбитали: Катион H^{+}; Что помнить на ЕГЭ: Полный органический аналог солей аммония.\n• **Ион гидроксония H3O^{+}** — Донор пары: Кислород O в H2O; Акцептор орбитали: Катион H^{+}; Что помнить на ЕГЭ: Существует в водных растворах кислот.\n• ****Угарный газ CO** (C≡O)** — Донор пары: Кислород O (пара); Акцептор орбитали: Углерод C (пустая 2p); Что помнить на ЕГЭ: 2 связи обменные + 1 ДАМ → валентность C и O равна III!…"}, "03": {"t": "Модуль 03. Характеристики ковалентной связи: σ/π-связи, длина, энергия и полярность молекулы", "x": "Прочность ковалентной связи зависит от её **кратности** (числа общих пар) и **радиуса атомов**: чем выше кратность и меньше атомы, тем короче и прочнее связь. А **полярность молекулы в целом** определяется её геометрией: если полярные связи тянут симметрично в разные стороны, их диполи взаимно гасятся."}, "03.1": {"t": "Модуль 03 · Главная мысль.", "x": "Прочность ковалентной связи зависит от её **кратности** (числа общих пар) и **радиуса атомов**: чем выше кратность и меньше атомы, тем короче и прочнее связь. А **полярность молекулы в целом** определяется её геометрией: если полярные связи тянут симметрично в разные стороны, их диполи взаимно гасятся."}, "03.5": {"t": "Модуль 03 · 1. Кратность связи: σ- и π-связи", "x": "• **Одинарная (C–C, H–H)** — 1; 1 σ; Самая длинная (0,154 нм); Наименьшая\n• **Двойная (C=C, O=O)** — 2; 1 σ + 1 π; Короче (0,134 нм); Выше одинарной\n• **Тройная (C≡C, N≡N, C≡O)** — 3; 1 σ + 2 π; Самая короткая (0,120 нм); Наибольшая"}, "03.8": {"t": "Модуль 03 · 2. Длина и энергия связи: два простых закона", "x": "• **Правило кратности:** в ряду C–C → C=C → C≡C кратность растёт, атомы стягиваются ближе → длина **уменьшается**, энергия **растёт**.\n• **Правило радиуса (галогеноводороды):** в ряду HF → HCl → HBr → HI радиус галогена растёт сверху вниз по группе → связь становится **длиннее**, а энергия связи **падает** (HF — самая короткая и прочная связь, поэтому плавиковая кислота слабая, а HI — самая длинная и легко разрывается)."}, "03.12": {"t": "Модуль 03 · Как быстро отличить неполярную молекулу от полярной", "x": "• **Условие** — Неполярная молекула (μ = 0): Все атомы вокруг центра одинаковы И на центральном атоме нет неподелённых пар (либо молекула из двух одинаковых атомов); Полярная молекула (μ ≠ 0): Либо атомы вокруг центра разные, либо на центральном атоме есть неподелённые пары, изгибающие форму\n• **Примеры неорганики** — Неполярная молекула (μ = 0): H2, O2, N2, Cl2, CO2, CS2, SO3, BF3, SiH4, SF6; Полярная молекула (μ ≠ 0): HCl, HF, H2O, H2S, NH3, PH3, SO2, CO, NO\n• **Примеры органики** — Неполярная молекула (μ = 0): CH4, CCl4, CF4, C2H6, C2H4, C2H2, бензол C6H6; Полярная молекула (μ ≠ 0): CH3Cl, CHCl3, CH3OH, CH3CHO, CH3COOH, CH3NH2"}, "03.15": {"t": "Модуль 03 · 4. Разбор вслух: считаем σ/π-связи и проверяем полярность", "x": "**Задача:** определи число σ- и π-связей и полярность молекулы в CO2, H2O, CH4, NH3 и C2H2.\n**Шаг 1 — CO2 (O=C=O):** две двойные связи → 2 σ и 2 π. Связи C=O полярны, но геометрия линейная (180°), диполи взаимно гасятся → **молекула неполярна**.\n**Шаг 2 — H2O (H–O–H):** две одинарные связи → 2 σ и 0 π. На кислороде две неподелённые пары, молекула угловая (104,5°) → **молекула полярна**.\n**Шаг 3 — CH4 и NH3:** в метане CH4 четыре одинарные связи C–H (4 σ, 0 π), на углероде нет неподелённых пар, форма правильного тетраэдра → **молекула неполярна**. В аммиаке NH3 три связи N–H (3 σ, 0 π) и неподелённая пара на азоте, форма треугольной пирамиды → **молекула полярна**.\n**Шаг 4 — C2H2 (H–C≡C–H):** две одинарные C–H (2 σ) и одна тройная C≡C (1 σ + 2 π) → всего 3 σ и 2 π. Молекула линейна и симметрична → **молекула неполярна**."}, "04": {"t": "Модуль 04. Ионная и металлическая связь: все ловушки солей, щелочей и сплавов", "x": "[[Ионная связь]] держит вместе катионы и анионы во всех **солях** (включая соли аммония, аминов, органические и комплексные соли), **щелочах**, **гидридах**, **пероксидах** и большинстве **оксидов/гидроксидов металлов**. А [[Металлическая связь|металлическая связь]] существует **только** в простых веществах-металлах и их сплавах — никогда в солях или оксидах!"}, "04.1": {"t": "Модуль 04 · Главная мысль.", "x": "[[Ионная связь]] держит вместе катионы и анионы во всех **солях** (включая соли аммония, аминов, органические и комплексные соли), **щелочах**, **гидридах**, **пероксидах** и большинстве **оксидов/гидроксидов металлов**. А [[Металлическая связь|металлическая связь]] существует **только** в простых веществах-металлах и их сплавах — никогда в солях или оксидах!"}, "04.4": {"t": "Модуль 04 · 1. Ионная связь: не только «металл + неметалл»", "x": "Но если сложный катион состоит только из неметаллов — например, катион аммония NH4^{+} или катион метиламмония CH3NH3^{+} — он ведёт себя точно так же, как ион Na^{+} или K^{+}! Поэтому между NH4^{+} и Cl^{−} (или NO3^{−}, SO4^{2−}, CH3COO^{−}) образуется полноценная **ионная связь**."}, "04.8": {"t": "Модуль 04 · 2. Комбинированные связи: конструктор сложных ионных веществ", "x": "• **Бинарные соли, оксиды, гидриды металлов (NaCl, CaCl2, MgO, NaH, CaH2)** — Да; Нет; Нет; Нет\n• **Щёлочи, амфотерные гидроксиды, оксосоли (KOH, Al(OH)3, Zn(OH)2, K2SO4, CaCO3, NaHCO3)** — Да; Да (O–H, S–O, C–O); Нет; Нет (в NO3^{−} — да)\n• **Пероксиды металлов, пирит, карбид кальция (Na2O2, FeS2, CaC2)** — Да; Нет; Да (O–O, S–S, C≡C); Нет\n• **Соли аммония и аминов (NH4Cl, NH4NO3, CH3NH3Cl)** — Да; Да (N–H, C–H); Нет (если 1 атом C); Да (в NH4^{+} / RNH3^{+})\n• **Органические соли и алкоголяты с ≥ 2 C (C2H5ONa, CH3COONa, C6H5ONa)** — Да; Да (C–H, C–O); Да (C–C); Нет\n• **Формиат и метилат (HCOONa, CH3ONa)** — Да; Да (C–H, C–O); **Нет** (всего 1 атом C!); Нет\n• **Комплексные соли (K2[Zn(OH)4], Na[Al(OH)4], K3[Fe(CN)6])** — Да; Да (O–H, C≡N); Нет; Да (внутри [...])\n• **Кристаллогидраты (CuSO4·5H2O, CaSO4·2H2O, Na2SO4·10H2O)** — Да; Да (O–H, S–O); Нет; Да (в аквакомплексе) + **водородная связь**"}, "04.9": {"t": "Модуль 04 · Граница школьной модели (95–100 баллов)", "x": "**Граница модели: когда «металл + неметалл» НЕ даёт ионную связь?** Чем выше степень окисления металла (+6, +7) и меньше радиус катиона, тем сильнее он притягивает электронное облако аниона — связь становится **ковалентной полярной**. Главные примеры на 100 баллов: высшие кислотные оксиды **CrO3** и **Mn2O7** (а также TiCl4, SnCl4, газообразные BeCl2, AlCl3) имеют **ковалентную полярную связь** и молекулярное строение! А вот оксиды металлов со степенями окисления +1..+4 (Na2O, MgO, Fe2O3, Al2O3, ZnO, Cr2O3) в школьной модели ЕГЭ-4 относятся к **ионной связи и ионной решётке**."}, "04.13": {"t": "Модуль 04 · Ловушка ЕГЭ: металл в формуле ≠ металлическая связь", "x": "**Два жёстких правила по металлической связи:** 1) Она есть **только** в простых веществах-металлах (Na, Fe, Cu, Al, Au, **включая жидкую ртуть Hg**!) и в **сплавах** (бронза, латунь, сталь, чугун, дюралюминий). 2) В сложных соединениях металлов (NaCl, Fe2O3, KOH, CuSO4) **металлической связи НЕТ** — там связь ионная!"}, "04.15": {"t": "Модуль 04 · 4. Разбор вслух: полная раскладка связей в сложных солях", "x": "**Задача:** распиши все виды химической связи в веществах C2H5ONa, CH3COONa, HCOONa, NH4NO3 и K2[Zn(OH)4].\n**Шаг 1 — этилат натрия C2H5ONa и ацетат натрия CH3COONa:** между O^{−} и Na^{+} — **ионная**; между C–H, C–O (и C=O в ацетате) — **ковалентная полярная**; между двумя углеродами C–C — **ковалентная неполярная**. В обеих солях сразу три вида связи!\n**Шаг 2 — формиат натрия HCOONa:** между O^{−} и Na^{+} — **ионная**; между H–C, C=O, C–O — **ковалентная полярная**. Атом углерода один, значит ковалентной неполярной связи здесь **нет**.\n**Шаг 3 — нитрат аммония NH4NO3:** между NH4^{+} и NO3^{−} — **ионная** (хотя металлов нет!); внутри обоих ионов — **ковалентная полярная** (N–H и N–O), причём в обоих ионах есть **донорно-акцепторный механизм**.…"}, "05": {"t": "Модуль 05. Водородная связь и силы Ван-дер-Ваальса: золотое правило F, O, N", "x": "Межмолекулярная [[Водородная связь|водородная связь]] между одинаковыми молекулами возникает **только тогда**, когда в молекуле атом водорода **напрямую связан с одним из трёх элементов: F, O или N** (группы H–F, –O–H, –N–H). Если водород сидит только на углероде (C–H), как в альдегидах, кетонах, эфирах и третичных аминах, — между их собственными молекулами водородной связи НЕТ."}, "05.1": {"t": "Модуль 05 · Главная мысль.", "x": "Межмолекулярная [[Водородная связь|водородная связь]] между одинаковыми молекулами возникает **только тогда**, когда в молекуле атом водорода **напрямую связан с одним из трёх элементов: F, O или N** (группы H–F, –O–H, –N–H). Если водород сидит только на углероде (C–H), как в альдегидах, кетонах, эфирах и третичных аминах, — между их собственными молекулами водородной связи НЕТ."}, "05.8": {"t": "Модуль 05 · 2. Почему водородная связь в 5–10 раз сильнее обычных сил", "x": "Водородные связи «поднимают» температуру кипения H2O почти на 180 °C выше ожидаемого тренда по молярной массе (аналогично HF > HI > HBr > HCl; в VA группе аммиак NH3 (−33 °C) кипит выше PH3 и AsH3, но уступает тяжёлому SbH3 (−17 °C): SbH3 > NH3 > AsH3 > PH3)."}, "05.10": {"t": "Модуль 05 · Межмолекулярная водородная связь между одинаковыми молекулами", "x": "• **Неорганика** — ЕСТЬ (прямая связь H–F, H–O, H–N): HF, H2O, H2O2, NH3, N2H4, кислородсодержащие кислоты (HNO3, H2SO4, H3PO4); НЕТ (главные ловушки ЕГЭ!): HCl, HBr, HI, H2S, PH3, CH4, SiH4, H2, O2, CO2, NaCl, NaOH (ионные кристаллы)\n• **Кислородная органика** — ЕСТЬ (прямая связь H–F, H–O, H–N): **Спирты** (CH3OH, C2H5OH, этиленгликоль, глицерин), **фенолы** (C6H5OH), **карбоновые кислоты** (HCOOH, CH3COOH — образуют димеры!), **углеводы** (глюкоза, сахароза, целлюлоза); НЕТ (главные ловушки ЕГЭ!): **Простые эфиры** (CH3–O–CH3), **альдегиды** (HCHO, CH3CHO), **кетоны** (CH3COCH3), **сложные эфиры** (CH3COOCH3) — в них O не связан с H!…"}, "05.11": {"t": "Модуль 05 · Ловушка ЕГЭ: изомеры с разным строением", "x": "**Ловушка «буквы в формуле есть, а связи нет»:** у диметилового эфира C2H6O (CH3–O–CH3) и этанола C2H6O (CH3–CH2–OH) **одинаковая брутто-формула**! Но у этанола есть группа –O–H → он кипит при +78 °C (есть водородные связи), а у диметилового эфира кислород зажат между двумя углеродами → он газ при комнатной температуре (t_кип = −24 °C, водородных связей нет!). Точно так же уксусная кислота CH3COOH образует прочные димеры, а её изомер метилформиат HCOOCH3 водородных связей не образует."}, "06": {"t": "Модуль 06. Молекулярное и немолекулярное строение. Четыре типа кристаллических решёток", "x": "Все кристаллические вещества делятся на два мира: **молекулярного строения** (молекулярная решётка — отдельные молекулы) и **немолекулярного строения** (ионная, атомная и металлическая решётки — единый бесконечный каркас без отдельных молекул). Тип решётки **не совпадает автоматически** с типом химической связи!"}, "06.1": {"t": "Модуль 06 · Главная мысль.", "x": "Все кристаллические вещества делятся на два мира: **молекулярного строения** (молекулярная решётка — отдельные молекулы) и **немолекулярного строения** (ионная, атомная и металлическая решётки — единый бесконечный каркас без отдельных молекул). Тип решётки **не совпадает автоматически** с типом химической связи!"}, "06.8": {"t": "Модуль 06 · 2. Короткий канонический список атомной решётки", "x": "• **Простые вещества (5 элементов)** — **Алмаз (C)**, **графит (C)**, **кремний (Si)**, **бор (B)**, **германий (Ge)**, а также **красный и чёрный фосфор (P)**.\n• **Сложные вещества (3 главных хита)** — **Оксид кремния(IV) (SiO2 — кварц, кремнезём, песок)**, **карбид кремния (SiC — карборунд)**, **нитрид бора (BN)**."}, "06.9": {"t": "Модуль 06 · Почему CO2 молекулярный, а SiO2 — атомный?", "x": "Почему CO2 — газ, а SiO2 — тугоплавкий кварц? У маленького углерода C (2-й период) p-орбитали легко образуют прочные двойные π-связи O=C=O → получаются замкнутые отдельные молекулы CO2. У крупного кремния Si (3-й период) боковое перекрывание 3p-орбиталей с 2p-орбиталями кислорода невыгодно — вместо двойной связи каждый атом Si образует **четыре одинарные связи Si–O** с четырьмя соседями, сшивая весь кристалл в непрерывный атомный каркас!"}, "06.14": {"t": "Модуль 06 · 4. Аллотропия и решётка — главный капкан ЕГЭ", "x": "• **Фосфор P** — Молекулярная решётка: **Белый фосфор (P4)**; Атомная решётка: **Красный и чёрный фосфор**; Как отличить по свойствам: Белый — мягкий, легкоплавкий (44 °C), светится в темноте, ядовит; красный — полимер, тугоплавкий\n• **Углерод C** — Молекулярная решётка: Фуллерен C60 (редко в ЕГЭ); Атомная решётка: **Алмаз и графит**; Как отличить по свойствам: Алмаз — 3D-каркас (сверхтвёрдый), графит — слоистый (проводит ток, мягкий, в ЕГЭ — атомная)\n• **Сера S** — Молекулярная решётка: **Кристаллическая сера (S8)**; Атомная решётка: — (пластическая сера аморфна); Как отличить по свойствам: Хрупкий жёлтый кристалл, легко плавится (113 °C)\n• **Кислород O** — Молекулярная решётка: **Кислород (O2) и озон (O3)**; Атомная решётка: —; Как отличить по свойствам: Оба — газы при н.у."}, "06.15": {"t": "Модуль 06 · Граница школьной модели (95–100 баллов)", "x": "**Три пограничные тонкости на 100 баллов:** 1) **Графит** в науке имеет слоистую (атомно-молекулярную) решётку: внутри слоя атомы связаны прочными ковалентными связями, а слои держатся слабыми силами Ван-дер-Ваальса (поэтому графит мягкий и пишет на бумаге). В ЕГЭ-4 графит стабильно относят к **атомной решётке** (немолекулярное строение). 2) **Аминокислоты** (глицин H2N–CH2–COOH) в твёрдом виде существуют как биполярные цвиттер-ионы ^{+}H3N–CH2–COO^{−} (в группе –NH3^{+} есть донорно-акцепторная связь!), поэтому имеют высокую t_пл (разлагаются > 200 °C) и ионно-подобную решётку; в заданиях № 4 на однозначный выбор молекулярной решётки их не смешивают с обычными молекулярными веществами. 3) **Полимеры** (полиэтилен, крахмал, целлюлоза) имеют макромолекулярное (полимерное) строение, а не атомную решётку."}, "06.17": {"t": "Модуль 06 · 5. Разбор вслух: сортируем коварные пары по типу решётки", "x": "**Задача:** определи тип кристаллической решётки и строение (молекулярное / немолекулярное) для пар: P4 и P(красн.), CO2 и SiO2, I2 и C(графит), CrO3 и Cr2O3.\n**Шаг 2.** **Пара 1 — белый фосфор P4 vs красный фосфор P:** белый состоит из тетраэдрических молекул P4 → **молекулярная решётка** (молекулярное); красный — полимерный каркас → **атомная решётка** (немолекулярное).\n**Шаг 3.** **Пара 2 — CO2 vs SiO2:** CO2 (сухой лёд) состоит из отдельных линейных молекул → **молекулярная**; SiO2 (кварц, песок) входит в канонический список атомных решёток → **атомная** (немолекулярное).\n**Шаг 4.** **Пара 3 — I2 vs графит:** иод легко возгоняется в фиолетовый пар, состоит из двухатомных молекул I2 → **молекулярная**; графит в ЕГЭ — **атомная** (немолекулярное).…"}, "06.18": {"t": "Модуль 06 · Мост к КИМ (№ 4 КИМ (код 1.4))", "x": "**Как спрашивают:** «Выберите два вещества немолекулярного строения» или «Выберите два вещества с атомной кристаллической решёткой».\n**На чём ловят:** Три главные ошибки: 1) отнести SiO2 или NH4Cl к молекулярным (оба — немолекулярные!); 2) отнести H2SO4, H3PO4, P4 или глюкозу к немолекулярным (все — молекулярные!); 3) перепутать CO2 и SiO2.\n**Как читать:** Для вопроса «немолекулярное строение» собирай в одну корзину **три** класса: ионные + атомные + металлические."}, "07": {"t": "Модуль 07. Как кристаллическая решётка диктует физические свойства вещества", "x": "Физические свойства вещества — температура плавления, твёрдость, хрупкость, ковкость, летучесть, запах и электропроводность — напрямую вытекают из того, **какие частицы стоят в узлах решётки и как прочно они связаны**."}, "07.1": {"t": "Модуль 07 · Главная мысль.", "x": "Физические свойства вещества — температура плавления, твёрдость, хрупкость, ковкость, летучесть, запах и электропроводность — напрямую вытекают из того, **какие частицы стоят в узлах решётки и как прочно они связаны**."}, "07.7": {"t": "Модуль 07 · Физический паспорт каждого типа кристаллической решётки", "x": "• **Температура плавления** — Высокая (обычно 300–2500 °C); Очень высокая (1500–4000 °C), тугоплавкие; Низкая (газы, жидкости, легкоплавкие тв.); Разная: от −39 °C (Hg) до +3422 °C (W), обычно высокая\n• **Твёрдость и механика** — Твёрдые, но **хрупкие**; **Очень твёрдые** (алмаз — эталон; кроме мягкого слоистого графита), непластичные; Мягкие, хрупкие, летучие, **часто имеют запах**; От мягких (Na) до твёрдых (Cr), **ковкие и пластичные**\n• **Электропроводность (твёрдое)** — **Не проводят** (ионы зажаты в узлах!); **Не проводят** (кроме графита и полупроводников Si, Ge); **Не проводят** (нет свободных зарядов); **Отлично проводят** (свободные электроны)\n• **Электропроводность (расплав / раствор)** — **Проводят ток!** (ионы становятся подвижными); Не проводят (и не растворяются); Расплав не проводит; водный раствор кислот — проводит (диссоциация); Расплав проводит ток…"}, "07.8": {"t": "Модуль 07 · Ловушка ЕГЭ: твёрдая соль vs расплав", "x": "**Главная ловушка по электропроводности:** твёрдая поваренная соль NaCl **НЕ проводит электрический ток**, потому что ионы Na^{+} и Cl^{−} жёстко зафиксированы в узлах кристалла. Она начинает проводить ток только в **расплаве** или **водном растворе**. Если в задании сказано «проводит электрический ток **в твёрдом состоянии**» — это **металл** (или редкое исключение **графит**), но не ионная соль!"}, "07.10": {"t": "Модуль 07 · 3. Запах и летучесть — верный маркер молекулярной решётки", "x": "Чтобы мы почувствовали запах твёрдого вещества, его частицы должны легко отрываться с поверхности и улетать в воздух. Из ионного, атомного или металлического каркаса оторвать частицу при комнатной температуре практически невозможно — поэтому поваренная соль, кварц и золото не пахнут. А вот иод I2, ментол, камфора, нафталин, фенол и ванилин имеют резкий запах: их молекулы легко улетают, потому что решётка **молекулярная**."}, "07.12": {"t": "Модуль 07 · 4. Разбор вслух: узнаём тип решётки по описанию свойств", "x": "**Задача:** даны три безымянных кристаллических вещества X, Y и Z. Определи тип их решётки по физическому паспорту.\n**Шаг 2.** **Вещество X:** плавится при 801 °C, хрупкое, не проводит ток в твёрдом состоянии, но хорошо проводит в расплаве и водном растворе. → Высокая t_пл + хрупкость + проводимость именно в расплаве/растворе = **ионная решётка** (это NaCl).\n**Шаг 3.** **Вещество Y:** плавится при 114 °C, мягкое, возгоняется при слабом нагревании, имеет резкий запах, не проводит ток ни в твёрдом виде, ни в расплаве. → Низкая t_пл + летучесть + запах + изолятор = **молекулярная решётка** (это I2).\n**Шаг 4.** **Вещество Z:** плавится выше 1700 °C, очень твёрдое, нерастворимо в воде и органических растворителях, не проводит ток ни в твёрдом виде, ни в расплаве. → Сверхвысокая t_пл + высокая твёрдость + полная нерастворимость + не проводит даже в расплаве = **атомная решётка** (это SiO2)."}, "08": {"t": "Модуль 08. Стратегия задания № 4 ЕГЭ-2027: метод «Двойного фильтра» и полный разбор КИМ", "x": "Главный секрет задания № 4 — **метод «Двойного фильтра»**: сначала переведи все 5 названий в формулы, затем прогони их через **Фильтр 1** (тип кристаллической решётки или строения), и только оставшихся кандидатов прогони через **Фильтр 2** (вид химической связи или механизм). Никогда не смешивай два критерия в голове одновременно!"}, "08.1": {"t": "Модуль 08 · Главная мысль.", "x": "Главный секрет задания № 4 — **метод «Двойного фильтра»**: сначала переведи все 5 названий в формулы, затем прогони их через **Фильтр 1** (тип кристаллической решётки или строения), и только оставшихся кандидатов прогони через **Фильтр 2** (вид химической связи или механизм). Никогда не смешивай два критерия в голове одновременно!"}, "08.6": {"t": "Модуль 08 · 2. Словарь тривиальных названий для № 4", "x": "• **Кремнезём / кварц / песок** — Формула: SiO2; Решётка: Атомная; Ключевые связи (ловушка): Ковалентная полярная (не путать с CO2!)\n• **Карборунд** — Формула: SiC; Решётка: Атомная; Ключевые связи (ловушка): Ковалентная полярная\n• **Сухой лёд** — Формула: CO2; Решётка: Молекулярная; Ключевые связи (ловушка): Ковалентная полярная (молекула неполярна)\n• **Пирит / железный колчедан** — Формула: FeS2; Решётка: Ионная; Ключевые связи (ловушка): Ионная + **ковал. неполярная** (S–S)\n• **Нашатырь (не путать с нашатырным спиртом NH3·H2O!)** — Формула: NH4Cl; Решётка: Ионная; Ключевые связи (ловушка): Ионная + ковал. полярная + **ДАМ** (без металлов!)\n• **Аммиачная селитра** — Формула: NH4NO3; Решётка: Ионная; Ключевые связи (ловушка): Ионная + ковал. полярная + **ДАМ**\n• **Медный купорос / гипс** — Формула: CuSO4·5H2O / CaSO4·2H2O; Решётка: Ионная; Ключевые связи (ловушка): Ионная + КПС + **ДАМ** + **водородная связь**…"}, "08.9": {"t": "Модуль 08 · Кейс 1 · Официальная Демоверсия ФИПИ ЕГЭ-2027", "x": "**Шаг 1.** **Условие (Демо-2027, № 4):** «Из предложенного перечня выберите два вещества с ковалентной полярной химической связью, которые имеют ионную кристаллическую решётку»: 1) хлорид кальция; 2) оксид фосфора(V); 3) этилат натрия; 4) аммиак; 5) гидроксид калия.\n**Шаг 1 — переводим в формулы:** 1) CaCl2; 2) P2O5 (P4O10); 3) C2H5ONa; 4) NH3; 5) KOH.\n**Шаг 2 — Фильтр 1 (ионная кристаллическая решётка):** P2O5 и NH3 — молекулярная решётка (отбрасываем 2 и 4). Остаются кандидаты: **1 (CaCl2), 3 (C2H5ONa), 5 (KOH)**.\n**Шаг 3 — Фильтр 2 (есть ковалентная полярная связь):** в бинарном CaCl2 только ионная связь (отбрасываем 1). В этилате натрия C2H5ONa есть связи C–H и C–O (ковалентные полярные), а в KOH есть связь O–H (ковалентная полярная).\n**Шаг 5.** **Ответ:** 35 (порядок цифр не важен: 35 или 53 — оба дают 1 балл)."}, "08.11": {"t": "Модуль 08 · Кейс 2 · Донорно-акцепторный механизм + немолекулярное строение", "x": "**Шаг 1.** **Условие:** «Выберите два вещества немолекулярного строения, в которых есть связь, образованная по донорно-акцепторному механизму»: 1) угарный газ; 2) хлорид аммония; 3) азотная кислота; 4) тетрагидроксоалюминат натрия; 5) аммиак.\n**Шаг 1 — формулы:** 1) CO; 2) NH4Cl; 3) HNO3; 4) Na[Al(OH)4]; 5) NH3.\n**Шаг 2 — Фильтр 1 (немолекулярное строение):** CO, HNO3 и NH3 имеют **молекулярное** строение (отбрасываем 1, 3, 5, хотя в CO и HNO3 есть ДАМ!). Остаются ионные соли **2 (NH4Cl)** и **4 (Na[Al(OH)4])**.\n**Шаг 3 — Фильтр 2 (ДАМ):** в NH4Cl катион аммония NH4^{+} содержит ДАМ; в комплексной соли Na[Al(OH)4] лиганды OH^{−} связаны с Al по ДАМ. Оба подходят!\n**Шаг 5.** **Ответ:** 24."}, "08.13": {"t": "Модуль 08 · Кейс 3 · Скрытая ковалентная неполярная связь + ионная решётка", "x": "**Шаг 1.** **Условие:** «Выберите два вещества ионного строения, в которых присутствует ковалентная неполярная связь»: 1) пероксид водорода; 2) пероксид натрия; 3) формиат натрия; 4) пирит; 5) хлорид натрия.\n**Шаг 1 — формулы:** 1) H2O2; 2) Na2O2; 3) HCOONa; 4) FeS2; 5) NaCl.\n**Шаг 2 — Фильтр 1 (ионная решётка):** H2O2 — молекулярное строение (отбрасываем 1, хотя там есть O–O!). Остаются **2 (Na2O2), 3 (HCOONa), 4 (FeS2), 5 (NaCl)**.\n**Шаг 3 — Фильтр 2 (ковалентная неполярная связь):** в Na2O2 есть мостик O–O (подходит!); в HCOONa только 1 атом углерода, связи C–C нет (отбрасываем 3!); в пирите FeS2 есть мостик S–S (подходит!); в NaCl только ионная связь (отбрасываем 5).\n**Шаг 5.** **Ответ:** 24."}, "08.15": {"t": "Модуль 08 · Кейс 4 · Межмолекулярная водородная связь + молекулярная решётка", "x": "**Шаг 1.** **Условие:** «Выберите два вещества молекулярного строения, между молекулами которых образуются водородные связи»: 1) диметиловый эфир; 2) этаналь; 3) фтороводород; 4) триметиламин; 5) уксусная кислота.\n**Шаг 1 — формулы:** 1) CH3–O–CH3; 2) CH3–CHO; 3) HF; 4) (CH3)3N; 5) CH3COOH.\n**Шаг 2 — Фильтр 1 (молекулярное строение):** все 5 веществ молекулярного строения.\n**Шаг 3 — Фильтр 2 (прямая связь H–F, H–O или H–N):** в 1, 2 и 4 водород связан только с углеродом C–H (ловушки, отбрасываем!). В HF есть прямая связь H–F, в CH3COOH есть группа –O–H.\n**Шаг 5.** **Ответ:** 35."}, "08.17": {"t": "Модуль 08 · Кейс 5 · Атомная решётка + ковалентная полярная связь", "x": "**Шаг 1.** **Условие:** «Выберите два вещества с атомной кристаллической решёткой и ковалентной полярной связью»: 1) кремнезём; 2) сухой лёд; 3) алмаз; 4) карборунд; 5) белый фосфор.\n**Шаг 1 — формулы:** 1) SiO2; 2) CO2; 3) C (алмаз); 4) SiC; 5) P4.\n**Шаг 2 — Фильтр 1 (атомная решётка):** CO2 и белый P4 — молекулярная решётка (отбрасываем 2 и 5). Остаются **1 (SiO2), 3 (C), 4 (SiC)**.\n**Шаг 3 — Фильтр 2 (ковалентная полярная связь):** в алмазе C все связи C–C неполярные (отбрасываем 3!). В SiO2 (Si–O) и SiC (Si–C) связи соединяют разные неметаллы — они ковалентные полярные.\n**Шаг 5.** **Ответ:** 14."}}, "_kt": "Задание 4 ЕГЭ по химии: химическая связь и кристаллические решётки с нуля до 100 баллов", "_mods": {"01": "Зачем атомы соединяются: электроотрицательность и карта таблицы ФИПИ", "02": "Ковалентная связь: скрытые неполярные связи и донорно-акцепторный механизм", "03": "Характеристики ковалентной связи: σ/π-связи, длина, энергия и полярность молекулы", "04": "Ионная и металлическая связь: все ловушки солей, щелочей и сплавов", "05": "Водородная связь и силы Ван-дер-Ваальса: золотое правило F, O, N", "06": "Молекулярное и немолекулярное строение. Четыре типа кристаллических решёток", "07": "Как кристаллическая решётка диктует физические свойства вещества", "08": "Стратегия задания № 4 ЕГЭ-2027: метод «Двойного фильтра» и полный разбор КИМ"}, "_skm": {"eo_bonds": ["01"], "covalent_dam": ["02"], "bond_props": ["03"], "ionic_metal": ["04"], "h_bonds": ["05"], "lattices": ["06"], "crystal_props": ["07"], "kim4_filter": ["08"]}, "_fig": []};
